'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let docs=[],categories=[],analyses=[],models=[],relations=[],texts=[],baseline={},changes=[],groups=[],byDoc={},byClaim={},byText={},byModel={};
let productCategory='',productQuery='',library={q:'',category:'',product:'',module:'',status:'',type:'',page:1},currentRoute='products';
const displayDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(value)?value.slice(0,10):value;
const known=c=>c&&c.claimsRead!==false&&c.features?.length>0;
const categoryName=id=>categories.find(c=>c.id===id)?.name||id;
const badge=(t,k='')=>`<span class="badge ${k}">${esc(t)}</span>`;
const relationName=r=>r.level==='confirmed'?'型号明确关联':r.level==='functional'?'功能相关 · 型号未确认':'相关专利候选 · 待核实';
const rels=id=>relations.filter(r=>r.productId===id&&!['excluded','rejected'].includes(r.level));
const docLink=(id,product='')=>`#patent/${encodeURIComponent(id)}${product?'?product='+encodeURIComponent(product):''}`;
let pdfIndex=null,pdfLoadIssue=false;
async function loadPdfIndex(){
 try{
  const response=await fetch('data/pdf-index.json');
  if(!response.ok)throw Error('PDF index unavailable');
  const index=await response.json();
  if(index.schemaVersion!==1||index.repository!=='wang10086-creator/chcnav-patent-pdfs'||!/^[a-f0-9]{40}$/.test(index.commit)||!index.documents||index.counts?.matched!==Object.keys(index.documents).length)throw Error('Invalid PDF index');
  for(const [id,record] of Object.entries(index.documents)){
   const parts=typeof record.path==='string'?record.path.split('/'):[];
   if(!/^CN\d+[A-Z]\d?$/.test(id)||!parts.length||parts.some(p=>!p||p==='.'||p==='..'||p.includes('\\'))||!parts.at(-1).startsWith(id+'_')||!record.path.toLowerCase().endsWith('.pdf'))throw Error('Invalid PDF record');
  }
  pdfIndex=index;
 }catch(e){pdfLoadIssue=true;console.warn('PDF index could not be loaded',e);}
}
function pdfLinks(id,compact=false){
 const record=pdfIndex?.documents?.[id],document=currentById[id]||byDoc[id];
 if(record&&document&&record.applicationNumber!==document.applicationNumber)return '<p class="sub">PDF 索引与此文献元信息不一致，暂不提供链接。</p>';
 if(!record)return `<p class="sub">${pdfLoadIssue?'PDF 索引暂未载入，请刷新重试。':'此文献版本暂无匹配 PDF。'}</p>`;
 const path=record.path.split('/').map(encodeURIComponent).join('/'),base=`https://github.com/${pdfIndex.repository}`;
 const view=`${base}/blob/${pdfIndex.commit}/${path}`,download=`https://raw.githubusercontent.com/${pdfIndex.repository}/${pdfIndex.commit}/${path}`;
 return `<p class="${compact?'sub':'pdf-links'}" data-pdf-publication="${esc(id)}"><a href="${esc(view)}" target="_blank" rel="noopener">阅读${compact?'':'本版本'} PDF ↗</a> · <a href="${esc(download)}" target="_blank" rel="noopener">下载 PDF ↓</a>${compact?'':`<br><span class="sub">${esc(id)} · ${(record.sizeBytes/1048576).toFixed(2)} MB · 用户提供的专利文献；当前法律状态仍待核验。</span>`}</p>`;
}
function stableApps(rs){return new Set(rs.map(r=>r.applicationNumber)).size}
function categoryDocs(id){return docs.filter(d=>d.categories.includes(id))}
function statCounts(rs){return {documents:rs.length,applications:stableApps(rs),text:rs.filter(d=>byText[d.id]?.available&&byText[d.id]?.claims?.length).length,analyzed:rs.filter(d=>known(byClaim[d.id])).length}}
function statHtml(s,scope='类别候选'){return `<div class="stats"><span><b>${s.applications}</b>${scope}申请</span><span><b>${s.documents}</b>文献版本</span><span><b>${s.text}</b>已取得权利要求文本</span><span><b>${s.analyzed}</b>已分析文献</span><span><b>${s.applications}</b>关联待核实申请</span></div>`}
function photo(m){return `<div class="product-visual">${m.localImage?`<img src="${esc(m.localImage)}" alt="${esc(m.name)} ${esc(m.model)} 官网产品图片" loading="lazy">`:'<div class="image-missing">尚未取得可核对的型号图片</div>'}<p class="sub">${esc(m.model)} · 官网型号</p><a class="sub" href="${esc(m.detailUrl)}" target="_blank" rel="noopener">产品详情与图片来源 ↗</a></div>`}
function statusBasic(d,c){const snap=c?.statusSnapshot;return `<div class="status">${esc(d.patentType==='发明申请'?'公开申请 · 尚不能据此确认授权':d.patentType+'公告')} ${esc(d.pubDate)}${snap?` · <a href="${esc(snap.sourceUrl)}" target="_blank" rel="noopener">第三方 ${esc(snap.displayedStatus)}</a>（${esc(snap.checkedAt)}查询）`:''} · 当前有效性${snap?'待官方核验':'未核验'}</div>`}
function patentBasic(d,pid=''){return `<div class="patent-basic"><a href="${docLink(d.id,pid)}">${esc(d.id)} ↗</a><strong class="patent-title-inline">${esc(d.title)}</strong>${statusBasic(d,byClaim[d.id])}</div>`}
function relationCard(r,compact=false){const d=byDoc[r.patentId],c=byClaim[r.patentId];if(!d)return '';return `<article class="relation"><div class="relation-head">${badge(relationName(r),r.level==='candidate'?'candidate':r.level==='confirmed'?'confirmed':'')}<span class="sub">${esc(r.module)}</span></div><h4>${esc(r.title)}</h4><p>${esc(r.summary)}</p><p><strong>关键限制：</strong>${esc(r.keyLimit)}</p>${patentBasic(d,r.productId)}${!compact?`<details><summary>为什么关联 · 查看证据与未确认环节</summary>${relationEvidence(r)}</details>`:`<div class="product-actions"><a href="#product/${r.productId}">查看关联依据 →</a><a href="${docLink(d.id,r.productId)}">展开权利要求 →</a></div>`}</article>`}
function relationEvidence(r){const m=byModel[r.productId],c=byClaim[r.patentId];return `<div class="evidence"><p><strong>官网功能依据</strong> · ${esc(r.officialEvidence.text)}</p><blockquote>${esc(r.officialEvidence.quote)}</blockquote><a href="${esc(r.officialEvidence.sourceUrl)}" target="_blank" rel="noopener">直达 ${esc(m.model)} 产品页 ↗</a><p style="margin-top:12px"><strong>专利对应依据</strong> · ${esc(r.claimEvidence.version)}，权利要求 ${r.claimEvidence.numbers.join('、')}</p><p>${esc(r.claimEvidence.text)}</p><a href="${docLink(r.patentId,r.productId)}">查看权利要求原文、限制与附图 →</a><p style="margin-top:12px"><strong>尚未确认</strong> · ${esc(r.unconfirmed)}</p><p class="smallnote">产品功能采集 ${esc(displayDate(m.collectedAt))} · 关系复核 ${esc(r.reviewedAt)} · 关联等级并非侵权或实施结论。</p>${reviewForm(r.id)}</div>`}
function modulesFor(d){return (docFns[d.id]||[]).map(x=>fnBy[x.functionId]?.name).filter(Boolean)}
function selectedDocs(){let rs=docs.filter(d=>(!library.category||d.categories.includes(library.category))&&(!library.product||rels(library.product).some(r=>r.patentId===d.id))&&(!library.module||modulesFor(d).includes(library.module))&&(!library.type||d.patentType===library.type));if(library.q){const q=library.q.toLowerCase();rs=rs.filter(d=>[d.id,d.title,d.applicationNumber,d.applicants,d.abstract,...modulesFor(d),...relations.filter(r=>r.patentId===d.id&&r.level!=='excluded').map(r=>byModel[r.productId]?.name)].join(' ').toLowerCase().includes(q))}if(library.status)rs=rs.filter(d=>library.status==='active'?byClaim[d.id]?.statusSnapshot?.displayedStatus==='Active':library.status==='unknown'?!byClaim[d.id]?.statusSnapshot:library.status==='analyzed'?known(byClaim[d.id]):library.status==='pending'?!known(byClaim[d.id]):library.status==='published'?d.patentType==='发明申请':d.patentType!=='发明申请');return rs.sort((a,b)=>b.pubDate.localeCompare(a.pubDate)||a.id.localeCompare(b.id))}
function recordRow(d,label=''){const c=byClaim[d.id],versions=groups.find(g=>g.applicationNumber===d.applicationNumber)?.documentIds||[];return `<article class="record"><h3><a href="${docLink(d.id)}">${esc(d.title)}</a></h3><div class="record-meta"><a href="${docLink(d.id)}">${esc(d.id)}</a><span>申请号 ${esc(d.applicationNumber)}</span><span>${esc(d.patentType)} · ${esc(d.pubDate)}</span>${badge(known(c)?'范围已初析':d.patentType==='外观设计'?'外观范围尚未分析':'范围尚未分析','unknown')}</div><p>${label?esc(label)+' · ':''}${d.categories.map(categoryName).map(esc).join(' / ')} · 技术模块初筛：${modulesFor(d).map(esc).join('、')||'待归类'}</p>${statusBasic(d,c)}${versions.length>1?`<p>同申请版本：${versions.map(v=>`<a href="${docLink(v)}">${esc(v)}</a>`).join(' · ')}（1 个申请，${versions.length} 个文献版本）</p>`:''}</article>`}
function libraryPage(){const moduleList=[...new Set(docs.flatMap(modulesFor))].sort();return `<div class="intro"><div><h1>全部专利</h1><p>完整保留 ${baseline.documentCount} 条文献 / ${baseline.applicationCount} 个去重申请；国际专利族尚未归组，数量未知。</p></div><span class="sub">Excel 原件不公开提供</span></div><p class="rule">默认浏览全量领域候选；按产品筛选只显示单独记录了证据的关系。A/B 文本分别保留，但按申请号计为同一申请。模块由标题／摘要初筛，不能作为保护范围结论。</p><div class="filters"><input id="lib-q" type="search" aria-label="搜索全部专利" placeholder="专利号、名称、申请号、产品、模块或技术关键词" value="${esc(library.q)}"><select id="lib-category" aria-label="类别筛选"><option value="">全部类别</option>${categories.map(c=>`<option value="${c.id}" ${library.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="lib-product" aria-label="产品关系筛选"><option value="">全部产品／未绑定型号</option>${models.map(m=>`<option value="${m.id}" ${library.product===m.id?'selected':''}>${esc(m.model)} · 仅有证据关系</option>`).join('')}</select><select id="lib-module" aria-label="技术模块筛选"><option value="">全部技术模块</option>${moduleList.map(m=>`<option ${library.module===m?'selected':''}>${esc(m)}</option>`).join('')}</select><select id="lib-type" aria-label="文献类型筛选"><option value="">全部文献类型</option>${['发明申请','发明授权','实用新型','外观设计'].map(t=>`<option ${library.type===t?'selected':''}>${t}</option>`).join('')}</select><select id="lib-status" aria-label="状态筛选">${[['','全部状态／进度'],['active','第三方 Active（未官方核验）'],['unknown','当前状态未获取'],['published','申请公布文献'],['grant','授权公告文献'],['analyzed','范围已初析'],['pending','范围尚未分析']].map(([v,t])=>`<option value="${v}" ${library.status===v?'selected':''}>${t}</option>`).join('')}</select><button class="button" id="reset-library">重置</button></div><div id="library-results"></div>`}
function updateLibrary(){const rs=selectedDocs(),totalPages=Math.max(1,Math.ceil(rs.length/20));library.page=Math.min(library.page,totalPages);const st=statCounts(rs);$('#library-results').innerHTML=`${statHtml(st,library.product?'已记录关系':'筛选候选')}<p class="sub">范围文本与分析数量按文献统计，两者可重叠；${library.product?'关联待核实 '+rels(library.product).filter(r=>r.level!=='confirmed').length+' 条关系。':'当前结果均需逐型号复核，不代表已确认产品覆盖。'}</p><div class="list">${rs.slice((library.page-1)*20,library.page*20).map(d=>recordRow(d)).join('')||'<div class="empty">无匹配记录。可清空筛选或更换关键词。</div>'}</div><div class="pager"><span>共 ${rs.length} 条文献 / ${st.applications} 个申请</span><div><button id="prev" ${library.page===1?'disabled':''}>上一页</button><span>${library.page} / ${totalPages}</span><button id="next" ${library.page===totalPages?'disabled':''}>下一页</button></div><button class="button" id="export-filter">导出当前结果</button></div>`;$('#prev').onclick=()=>{library.page--;updateLibrary()};$('#next').onclick=()=>{library.page++;updateLibrary();$('#library-results').scrollIntoView({block:'start'})};$('#export-filter').onclick=()=>download('chcnav-filtered-documents.json',rs)}
function rawClaims(c,id){const t=byText[id];if(!t?.available||!t.claims?.length)return '<p class="sub">尚未缓存可用的权利要求全文。请核对原文入口；已有分析摘要与原始附图继续保留。</p>';return `<p class="sub">${esc(t.version)} · ${esc(displayDate(t.retrievedAt))}取得 · <a href="${esc(t.sourceUrl)}" target="_blank" rel="noopener">文本来源 ↗</a>。下文为原文提取，需结合官方文献核对排版与公式。</p>${t.localPdf?`<p><a class="button" href="${esc(t.localPdf)}" target="_blank" rel="noopener">查看已缓存授权PDF ↗</a></p>`:''}${t.formulaImagesMayBeOmitted||t.plainTextComplete===false?'<p class="scope-warning">本件网页提取文本可能遗漏公式图，必须结合授权PDF核对，不将下方纯文本视为完整公式依据。</p>':''}${t.claimsPageImages?.length?disclosure('formula-pages-'+id,'展开公式原页（授权文献权利要求）',`<p class="sub">纯文本未完整保留公式；以下为授权原页影像，点击可放大。</p>${t.claimsPageImages.map((url,i)=>`<figure class="claim-page"><a href="${esc(typeof url==='string'?url:url.localUrl||url.url)}" target="_blank" rel="noopener"><img src="${esc(typeof url==='string'?url:url.localUrl||url.url)}" loading="lazy" alt="${esc(id)} 授权权利要求原页 ${i+1}"></a><figcaption>授权权利要求原页 ${i+1}</figcaption></figure>`).join('')}`):''}${t.claims.map(x=>`<details id="claim-${id}-${x.number}"><summary>权利要求 ${esc(x.number)}${(c?.claimNumbers||[]).includes(Number(x.number))?' · 已用于分析':''}</summary><p class="raw-claim">${esc(x.text)}</p></details>`).join('')}`}
function legacyPatentDetails(id,params){const d=byDoc[id];if(!d)return '<div class="empty">未找到该文献。<a href="#patents">返回全部专利</a></div>';const c=byClaim[id],versionIds=groups.find(g=>g.applicationNumber===d.applicationNumber)?.documentIds||[],pid=params.get('product'),back=byModel[pid]?`#product/${pid}`:'#patents';return `<a class="back" href="${back}">← ${byModel[pid]?'返回 '+esc(byModel[pid].model):'返回全部专利'}</a><h1 style="font-size:27px">${esc(d.title)}</h1><p><strong>${esc(id)}</strong> ${badge(d.patentType)} ${badge(known(c)?'权利要求已初析 · 待IP复核':'范围尚未分析','unknown')}</p>${statusBasic(d,c)}<div class="detail-panel"><dl class="meta-grid">${[['申请号',d.applicationNumber],['公开／公告号',d.id],['申请日',d.filingDate],['公开／公告日',d.pubDate],['清单申请人（非当前权属结论）',d.applicants],['原清单初筛依据（历史）',d.classificationBasis]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="sub">原始清单第 ${d.sourceRow} 行 · 同申请版本 ${versionIds.map(v=>`<a href="${docLink(v,pid||'')}">${esc(v)}</a>`).join(' · ')}</p></div><section class="detail-panel"><h2>法律状态与权属</h2>${c?.statusSnapshot?`<p><strong>第三方页面：${esc(c.statusSnapshot.displayedStatus)}</strong></p><p class="sub">${esc(c.statusSnapshot.provider)} · ${esc(displayDate(c.statusSnapshot.checkedAt))}查询 · <a href="${esc(c.statusSnapshot.sourceUrl)}" target="_blank" rel="noopener">核对状态来源 ↗</a></p><p>${esc(c.statusSnapshot.note)}</p>`:'<p>尚未取得当前法律状态。文献类型只说明公开／公告阶段。</p>'}<p>${esc(c?.legalStatusNote||'当前权属、年费及无效等状态尚未核验。')}</p><p class="sub">原申请人不等于当前权利人；第三方 Active 不等于官方确认有效。${c?.statusCheckAttempt?'最近获取尝试 '+esc(displayDate(c.statusCheckAttempt.attemptedAt))+'：'+esc(c.statusCheckAttempt.result):''}</p></section><section class="detail-panel"><h2>${d.patentType==='发明申请'?'公开申请技术方案（非已取得权利）':d.patentType==='外观设计'?'外观设计分析进度':'授权范围初析'}</h2>${known(c)?`<p>${esc(c.scopeSummary)}</p><p class="sub">文献版本 ${esc(id)} · 涉及权利要求 ${c.claimNumbers.join('、')} · ${esc(c.evidenceStatus)} · ${esc(displayDate(c.checkedAt)||'原核对日期见保留来源')}</p><h3>权利要求中的技术组合</h3><ol>${c.features.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>关键限制与从属限定</h3><ol>${c.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${c.abstractVsClaims?`<h3>公布／摘要与授权文本区别</h3><p>${esc(c.abstractVsClaims)}</p>`:''}`:`<p>${d.patentType==='外观设计'?'未完成正式图片或照片及简要说明的外观范围分析。下方摘要或类别标签不能替代外观分析。':esc(c?.scopeSummary||'尚未取得并分析足够的权利要求依据。不能由清单摘要推导保护范围。')}</p>${c?.limits?`<ul>${c.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}`}</section><section class="detail-panel"><h2>权利要求原文</h2>${rawClaims(c,id)}<p style="margin-top:14px"><a class="button" href="${esc(c?.sourceUrl||d.googlePatentsUrl)}" target="_blank" rel="noopener">打开对应文献原文 ↗</a>${c?.sourcePdf||c?.pdfUrl?` <a class="button" href="${esc(c.sourcePdf||c.pdfUrl)}" target="_blank" rel="noopener">授权PDF ↗</a>`:''}</p></section><section class="detail-panel drawings"><h2>原始附图与文本定位</h2>${(c?.drawings||[]).map((x,i)=>{if(typeof x==='string')return `<p><a href="${esc(x)}" target="_blank" rel="noopener">原始附图 ${i+1} ↗</a></p>`;return `<figure>${x.localUrl?`<img src="${esc(x.localUrl)}" alt="${esc(x.caption||x.label||'专利原始附图')}" loading="lazy">`:''}<figcaption>${esc(x.caption||x.label||'原始附图')} ${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener">原图来源 ↗</a>`:''}</figcaption></figure>`}).join('')||'<p class="sub">未提取原图；请通过文献原文或PDF查看。</p>'}${c?.evidenceLocations?`<p>${esc(Array.isArray(c.evidenceLocations)?c.evidenceLocations.join('；'):c.evidenceLocations)}</p>`:''}</section><section class="detail-panel"><h2>产品关联证据</h2>${relations.filter(r=>r.patentId===id&&r.level!=='excluded').map(r=>`<h3><a href="#product/${r.productId}">${esc(byModel[r.productId]?.name)}</a> ${badge(relationName(r),r.level==='candidate'?'candidate':'')}</h3>${relationEvidence(r)}`).join('')||'<p>尚无具体型号关联；保留为类别候选。</p>'}${relations.filter(r=>r.patentId===id&&r.level==='excluded').map(r=>`<div class="scope-warning">已撤下与 ${esc(byModel[r.productId]?.model)} 的直接图文绑定：${esc(r.reason)}</div>`).join('')}${c?.associationBasis?`<details><summary>保留的旧版领域关联依据</summary><p>${esc(c.associationBasis)}</p><p class="sub">仅为原分析记录，不自动升级为当前型号关联。</p></details>`:''}${reviewForm('document:'+id)}</section><details class="detail-panel"><summary>清单摘要、版本与其他原始来源</summary><p style="margin-top:14px">${esc(d.abstract)}</p><p class="sub">摘要只用于初筛，不替代权利要求／外观范围。</p>${(c?.relatedSources||[]).map(s=>typeof s==='string'?{url:s}:s).filter(s=>s&&typeof s.url==='string'&&s.url.trim()).map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label||'相关来源')} ↗</a></p>`).join('')}<a href="data/claims.json" download>完整保留的分析数据 ↓</a></details>`}
function reviews(){try{return JSON.parse(localStorage.getItem('chcnav-review-drafts-v1')||'{}')}catch{return {}}}
function reviewForm(key){const saved=reviews()[key];return `<details class="review"><summary>人工复核记录${saved?' · 已保存本机草稿':''}</summary><form class="review-form" data-review="${esc(key)}"><p class="sub">仅保存于当前浏览器，不会改变公开关联等级。可导出交由维护者审核合并。</p><label>复核建议<select name="decision"><option value="pending" ${saved?.decision==='pending'?'selected':''}>继续待核实</option><option value="support" ${saved?.decision==='support'?'selected':''}>补充证据支持关联</option><option value="exclude" ${saved?.decision==='exclude'?'selected':''}>建议排除关联</option></select></label><label>证据链接与理由<textarea name="note" required placeholder="填写对应型号材料、权利要求依据及核对说明">${esc(saved?.note||'')}</textarea></label><button class="button" type="submit">保存本机复核草稿</button> <button class="button" type="button" data-export-reviews>导出全部复核草稿</button><p class="review-output">${saved?'上次保存 '+esc(displayDate(saved.savedAt)):''}</p></form></details>`}
function updatesPage(){return `<h1>更新记录</h1><p class="sub">静态画像／手动更新；未接入自动检索或定时任务。刷新页面不会改变资料核验时间。</p><div class="summary-grid"><div><h3>完整数据基线</h3><p>${baseline.documentCount} 条文献，${baseline.applicationCount} 个去重申请，${baseline.versionLinkedApplications} 个申请保留多个版本。专利族数量未知。</p><p>原有 ${baseline.analyzedDocuments} 件权利要求初析、2 件缺失文本记录、原始Excel、图片及附图全部保留。</p></div><div><h3>本版关联覆盖</h3><p>${models.length} 个真实型号；${relations.filter(r=>r.level==='confirmed').length} 条型号明确关联，${relations.filter(r=>r.level==='functional').length} 条功能关联，${relations.filter(r=>r.level==='candidate').length} 条型号候选。${relations.filter(r=>r.level==='excluded').length} 条不充分绑定已纠正。</p><p>产品来源采集 2026.11.01；法律状态为独立保存的第三方查询快照，未官方确认。</p></div></div>${changes.map(c=>`<article class="changelog"><time>${esc(displayDate(c.date))}</time><h3>${esc(c.title)}</h3><ul>${c.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></article>`).join('')}<section class="detail-panel"><h2>资料缺口</h2><ul><li>未取得任何型号实施特定权利要求的直接证明，不把功能相符标为型号确认。</li><li>未完成全量934条文献的权利要求精读；外观设计148条尚未完成外观范围分析。</li><li>当前有效性、年费、无效和当前权属待官方登记核验；国际同族未归组。</li><li>图片缺失或原文不可得的条目明确保留，不推断无保护或自由实施。</li></ul></section><section class="detail-panel"><h2>原始数据与复核资料</h2><div class="downloads"><span class="sub">Excel 原件不公开提供</span><a href="data/portfolio.json" download>全部原始文献</a><a href="data/claims.json" download>既有范围分析与状态来源</a><a href="data/product-catalog.json" download>型号与官网证据</a><a href="data/product-relations.json" download>逐条关联证据</a><a href="data/claim-texts.json" download>缓存权利要求文本</a><a href="data/baseline.json" download>修改前基线及文件校验值</a><button class="linkbutton" data-export-reviews>导出本机复核草稿</button></div><p class="sub" style="margin-top:12px">原始数据文件保持不变；本版另建产品实体、关系证据和文献索引。复核草稿只在本机保存，未提交到公开站点。</p></section>`}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bindLibrary(){$('#lib-q').oninput=ev=>{library.q=ev.target.value;library.page=1;updateLibrary()};for(const k of ['category','product','module','status','type'])$('#lib-'+k).onchange=ev=>{library[k]=ev.target.value;library.page=1;updateLibrary()};$('#reset-library').onclick=()=>{library={q:'',category:'',product:'',module:'',status:'',type:'',page:1};history.replaceState(null,'','#patents');render()}}
function bindReviews(){document.querySelectorAll('[data-export-reviews]').forEach(b=>b.onclick=()=>download('chcnav-review-drafts.json',reviews()));document.querySelectorAll('.review-form').forEach(f=>f.onsubmit=ev=>{ev.preventDefault();const data=new FormData(f),all=reviews();all[f.dataset.review]={key:f.dataset.review,decision:data.get('decision'),note:String(data.get('note')).trim(),savedAt:new Date().toISOString(),scope:'browser-local-draft'};try{localStorage.setItem('chcnav-review-drafts-v1',JSON.stringify(all));f.querySelector('.review-output').textContent='已保存本机草稿；未更改公开关联。'}catch{f.querySelector('.review-output').textContent='本机存储不可用，请复制备注或导出保存。'}})}
// Shared functional index and view state. Original documents and analyses remain authoritative.
let fx={},fnBy={},docFns={},dualReady=false,unifiedQuery='',searchPage=1,openNodes=new Set(),listLimits={},viewScroll={},lastView='',searchFilter='all';
const functionIds=mid=>Object.keys(fx.modelFunctions?.[mid]||{});
const functionDocs=fid=>docs.filter(d=>docFns[d.id]?.some(f=>f.functionId===fid));
const activeRelations=()=>relations.filter(r=>['functional','confirmed'].includes(r.level));
const relationsForFunction=fid=>activeRelations().filter(r=>(fx.relationFunctions[r.id]||[]).includes(fid));
const uniqueDocs=rs=>[...new Map(rs.map(d=>[d.id,d])).values()];
const appsCount=rs=>new Set(rs.map(d=>d.applicationNumber)).size;
function candidateDocs(mid){const fs=functionIds(mid),m=byModel[mid],excludedApps=new Set(relations.filter(r=>r.productId===mid&&r.level==='excluded').map(r=>byDoc[r.patentId]?.applicationNumber)),evidenceApps=new Set(rels(mid).map(r=>byDoc[r.patentId]?.applicationNumber));return categoryDocs(m.categoryId).filter(d=>!excludedApps.has(d.applicationNumber)&&!evidenceApps.has(d.applicationNumber)&&docFns[d.id]?.some(f=>fs.includes(f.functionId)))}
function disclosure(key,title,body,cls='fold'){return `<details class="${cls}" data-open-key="${key}" ${openNodes.has(key)?'open':''}><summary>${title}</summary>${body}</details>`}
function compactPatent(d,rr=[],candidate=false){return `<article class="compact-patent"><a class="patent-link" href="${docLink(d.id)}"><strong>${esc(d.id)}</strong> ${esc(d.title)}</a><div>${badge(candidate?'领域候选 · 未核实型号':rr.some(r=>r.level==='confirmed')?'型号明确关联':'功能相关 · 型号未确认',candidate?'candidate':'')}${known(byClaim[d.id])?'<span class="sub"> · 范围已初析</span>':'<span class="sub"> · 范围尚未分析</span>'}</div>${statusBasic(d,byClaim[d.id])}${rr.length?`<p class="sub">涉及产品：${[...new Set(rr.map(r=>r.productId))].map(mid=>`<a href="#product/${mid}">${esc(byModel[mid].model)}</a>`).join('、')} · 功能：${[...new Set(rr.flatMap(r=>fx.relationFunctions[r.id]||[]))].map(fid=>`<a href="#functions/${fid}">${esc(fnBy[fid].name)}</a>`).join('、')}</p>`:''}</article>`}
function pagedPatents(ds,key,rr=[],candidate=false){const limit=listLimits[key]||12;return `<div class="compact-list">${ds.slice(0,limit).map(d=>compactPatent(d,rr.filter(r=>r.patentId===d.id),candidate)).join('')||'<p class="sub">暂无符合条件的记录。</p>'}</div><div class="list-count">已显示 ${Math.min(limit,ds.length)} / ${ds.length} 条文献 · ${appsCount(ds)} 个申请 ${ds.length>limit?`<button class="button" data-more="${key}">加载更多</button>`:''}</div>`}
function modelCard(m){const rr=rels(m.id),evidence=rr.filter(r=>r.level!=='candidate'),ds=uniqueDocs(evidence.map(r=>byDoc[r.patentId])),fs=functionIds(m.id),candidate=candidateDocs(m.id);return `<article class="product-hero compact-model" id="model-${m.id}">${photo(m)}<div class="product-copy"><div class="eyebrow">${esc(categoryName(m.categoryId))}</div><h2><a href="#product/${m.id}">${esc(m.name)}</a></h2><p class="purpose">${esc(m.purpose)}</p><ul class="scope-lines">${evidence.length?evidence.map(r=>`<li><a href="${docLink(r.patentId,m.id)}">${esc(r.title)} →</a><span>${esc(r.keyLimit)}</span></li>`).join(''):`<li>${esc(m.officialFeatures[0].text)}</li><li class="sub">尚无足够证据建立具体专利的功能关联；已有类别文献继续保留为候选。</li>`}</ul>${evidence.length?'<p class="sub">以上均为功能相关，型号实施尚未确认；每行对应独立专利依据。</p>':''}<div class="card-folds">${disclosure('mf-'+m.id,`相关功能（${fs.length}）`,`<div class="function-chips">${fs.map(fid=>`<a href="#functions/${fid}">${esc(fnBy[fid].name)} →</a>`).join('')}</div>`)}${disclosure('mp-'+m.id,`关联专利（${appsCount(ds)} 个申请）`,`<p class="sub">${ds.length} 条文献；${ds.filter(d=>known(byClaim[d.id])).length} 件已分析；${evidence.filter(r=>r.level!=='confirmed').length} 条关系待型号核实。未声称覆盖本产品全部专利。</p>${pagedPatents(ds,'mp-'+m.id,evidence)}`)}</div><div class="product-actions"><a href="#product/${m.id}">查看产品与核对范围 →</a><a href="#product/${m.id}?candidates=1">领域初筛候选（${appsCount(candidate)} 个申请）</a></div></div></article>`}
function browseShell(view,body){return `<section class="browse-head"><div><h1>产品与专利，按需展开。</h1><p class="sub">功能关联与领域候选分别展示。每项结论可追溯到原文与型号依据。</p></div><div class="segmented" aria-label="浏览方式"><a href="#products" class="${view==='products'?'selected':''}">按产品</a><a href="#functions" class="${view==='functions'?'selected':''}">按功能</a></div></section>${searchShell()}${body}`}
function searchShell(){return `<div class="unified-search"><label class="sr-only" for="unified-q">搜索产品、功能或专利</label><input id="unified-q" type="search" value="${esc(unifiedQuery)}" placeholder="搜索范围特征、功能、产品类型或专利号"><button class="button" id="clear-search">清除</button></div><section id="unified-results" aria-live="polite"></section>`}
function productsPage(){const shown=models.filter(m=>!productCategory||m.categoryId===productCategory);return browseShell('products',`<div class="filters"><label for="product-category">产品类别</label><select id="product-category"><option value="">全部类别</option>${categories.filter(c=>c.id!=='shared').map(c=>`<option value="${c.id}" ${productCategory===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="sub">${shown.length} 个型号</span>${productCategory?'<button id="clear-category" class="linkbutton">清除类别</button>':''}</div><div class="product-grid">${shown.map(modelCard).join('')}</div><p class="rule">首页关联专利数只计有逐条证据的关系；领域初筛候选另列。未找到关联，不代表没有专利保护。</p>`)}
function functionLeaf(f){const rr=relationsForFunction(f.id),eds=uniqueDocs(rr.map(r=>byDoc[r.patentId])),eapps=new Set(eds.map(d=>d.applicationNumber)),cds=functionDocs(f.id).filter(d=>!eapps.has(d.applicationNumber)),ms=models.filter(m=>functionIds(m.id).includes(f.id));return disclosure('fn-'+f.id,`<span>${esc(f.name)}</span><span class="sub">${ms.length} 产品 · ${appsCount(eds)} 关联申请 · ${appsCount(cds)} 候选申请</span>`,`<div class="function-body"><p>${esc(f.definition)}</p><p class="sub">搜索别名：${f.aliases.map(esc).join('、')}</p><div class="function-chips">${ms.map(m=>`<a href="#product/${m.id}">${esc(m.model)} →</a>`).join('')||'<span class="sub">尚无官网功能已核对的具体型号。</span>'}</div><p class="sub">上述产品具备此类功能，不表示下方每件专利均关联所有产品。</p><h3>有证据的产品关联</h3>${pagedPatents(eds,'fe-'+f.id,rr)}${disclosure('fc-'+f.id,`领域候选（${appsCount(cds)} 个申请） · 单独复核`,`<p class="rule">仅标题／摘要命中该功能词，不视为产品实施证明。不同产品适用范围须逐条核实。</p>${pagedPatents(cds,'fc-'+f.id,[],true)}`)}</div>`,'function-leaf')}
function functionsPage(){return browseShell('functions',`<p class="sub">${fx.functions.length} 个标准功能。分类数量按申请去重；同一申请可出现在多个功能下，各功能数量不可直接相加。</p><div class="function-tree">${fx.parents.map(p=>{const fs=fx.functions.filter(f=>f.parentId===p.id),ds=uniqueDocs(fs.flatMap(f=>functionDocs(f.id)));return disclosure('parent-'+p.id,`<strong>${esc(p.name)}</strong><span class="sub">${fs.length} 功能 · ${appsCount(ds)} 个初筛申请</span>`,fs.map(functionLeaf).join(''),'function-parent')}).join('')}</div><p class="rule">全量 ${docs.length} 条文献均已完成规则初筛；${fx.documents.filter(d=>!d.functions.length).length} 条未命中具体功能，继续保留于全部专利。规则分类不等于权利要求分析。</p><a href="#updates">查看功能归并清单与检查范围 →</a>`)}
function productDetails(id){const m=byModel[id];if(!m)return '<p>未找到产品。</p>';const cds=candidateDocs(id),excluded=relations.filter(r=>r.productId===id&&r.level==='excluded'),cat=categoryDocs(m.categoryId);return `${searchShell()}<a class="back" href="#products">← 返回按产品</a>${modelCard(m)}<p class="rule">已对全部934条文献标题／摘要执行功能初筛，其中本类别 ${cat.length} 条文献／${appsCount(cat)} 个申请；当前功能交集候选 ${cds.length} 条／${appsCount(cds)} 个申请。沿用已取得的9件授权文本分析，未完成其余文献精读，不能据此认定本型号全部相关专利已找齐。</p>${disclosure('pc-'+id,`领域初筛候选（${appsCount(cds)} 个申请） · 不计入上方关联数量`,`<p class="sub">同时满足类别与官网功能词线索；已排除上方有证据关系及已否定绑定的申请版本。此处不暗示型号实施。</p>${pagedPatents(cds,'pc-'+id,[],true)}`)}${disclosure('excluded-'+id,`已撤下的不充分绑定（${excluded.length}）`,excluded.map(r=>`<p><a href="${docLink(r.patentId)}">${r.patentId}</a>：${esc(r.reason)}</p>`).join('')||'<p>无历史排除记录。</p>')}${disclosure('official-'+id,'官网功能与逐型号来源',m.officialFeatures.map(f=>`<p>${esc(f.text)}</p><blockquote>${esc(f.quote)}</blockquote><a href="${esc(f.sourceUrl)}" target="_blank" rel="noopener">官网依据 ↗</a>`).join('')+`<p class="sub">采集日期 ${esc(displayDate(m.collectedAt))}</p>`)}<p><a href="#patents?category=${m.categoryId}">查看完整类别候选库（${cat.length} 条文献） →</a></p>`}
function oldGlobalMatches(){const q=unifiedQuery.trim().toLowerCase();if(!q)return [];const hit=s=>String(s).toLowerCase().includes(q),matchedFns=fx.functions.filter(f=>hit(f.name)||f.aliases.some(a=>['农机路径与掉头','无人船测深与定位','GNSS与惯性定位','放样与测量'].includes(a)?a.toLowerCase()===q:hit(a))),fidSet=new Set(matchedFns.map(f=>f.id)),matchedModels=models.filter(m=>hit(m.name+' '+m.model)),midSet=new Set(matchedModels.map(m=>m.id)),out=[];
 for(const m of models){const ff=functionIds(m.id).filter(f=>fidSet.has(f));if(midSet.has(m.id)||ff.length)out.push({type:'product',title:m.name,href:'#product/'+m.id,reason:midSet.has(m.id)?'命中产品名称／型号':'命中官网功能：'+ff.map(f=>fnBy[f].name).join('、'),context:'功能：'+functionIds(m.id).map(f=>fnBy[f].name).join('、')})}
 for(const f of matchedFns)out.push({type:'function',title:f.name,href:'#functions/'+f.id,reason:hit(f.name)?'命中标准功能名':'命中功能别名：'+f.aliases.filter(hit).join('、'),context:'涉及产品：'+models.filter(m=>functionIds(m.id).includes(f.id)).map(m=>m.model).join('、')});
 for(const d of docs){const rr=activeRelations().filter(r=>r.patentId===d.id),ff=(docFns[d.id]||[]).filter(x=>fidSet.has(x.functionId)),byProduct=rr.some(r=>midSet.has(r.productId)),direct=hit(d.id)||hit(d.title)||hit(d.applicationNumber),oldHit=(d.modules||[]).some(v=>v.toLowerCase()===q);if(direct||ff.length||byProduct||oldHit)out.push({type:'patent',title:d.id+' · '+d.title,href:docLink(d.id),reason:direct?'命中专利号／名称／申请号':byProduct?'命中有证据的产品关系':ff.length?'命中功能标准名或别名':'命中保留的旧模块名称',context:(rr.length?'涉及产品：'+rr.map(r=>byModel[r.productId].model).join('、'):'产品关联未确认')+' · 功能：'+((docFns[d.id]||[]).map(x=>fnBy[x.functionId].name).join('、')||'待归类'),doc:d})}
 return out;}
function oldRenderSearch(){const box=$('#unified-results');if(!box)return;const all=globalMatches(),rs=all.filter(r=>searchFilter==='all'||r.type===searchFilter),limit=searchPage*12;box.innerHTML=!unifiedQuery.trim()?'':`<div class="search-results"><div class="section-title"><h3>全量搜索 · ${rs.length} 条结果</h3><select id="search-kind" aria-label="搜索结果类型">${[['all','全部类型'],['product','产品'],['function','功能'],['patent','专利文献']].map(([v,n])=>`<option value="${v}" ${v===searchFilter?'selected':''}>${n}</option>`).join('')}</select></div>${rs.slice(0,limit).map(r=>`<article class="search-hit"><span class="sub">${{product:'产品',function:'功能',patent:'专利文献'}[r.type]}</span><a href="${r.href}">${esc(r.title)}</a><p class="sub">${esc(r.reason)} · ${esc(r.context)}</p>${r.doc?`<div class="sub">定位功能：${(docFns[r.doc.id]||[]).map(x=>`<a href="#functions/${x.functionId}">${esc(fnBy[x.functionId].name)}</a>`).join(' · ')||'尚未归类'}</div>`:''}</article>`).join('')||'<div class="empty">未找到匹配项。请尝试专利号、型号、标准功能名或别名。</div>'}<div class="list-count">已显示 ${Math.min(limit,rs.length)} / ${rs.length}${rs.length>limit?'<button id="search-more" class="button">加载更多</button>':''}</div></div>`;$('#search-kind')?.addEventListener('change',e=>{searchFilter=e.target.value;searchPage=1;renderSearch()});$('#search-more')?.addEventListener('click',()=>{searchPage++;renderSearch()});}
let drawerOrigin=null;
function openPatent(id,pid=''){if(currentReady&&currentById[id])return openCurrentPatent(id);if(!byDoc[id])return;drawerOrigin=document.activeElement;let dialog=$('#patent-drawer');if(!dialog){dialog=document.createElement('dialog');dialog.id='patent-drawer';dialog.setAttribute('aria-label','专利详情');document.body.append(dialog);dialog.addEventListener('close',()=>{document.body.classList.remove('drawer-open');drawerOrigin?.focus?.()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}dialog.innerHTML=`<div class="drawer-top"><strong>专利详情 · ${esc(id)}</strong><button id="drawer-close" aria-label="关闭专利详情">关闭 ×</button></div><div class="drawer-content">${patentDetails(id,new URLSearchParams(pid?'product='+pid:''))}</div>`;dialog.querySelector('.back')?.remove();$('#drawer-close').onclick=()=>dialog.close();bindReviews();if(!dialog.open){dialog.showModal();document.body.classList.add('drawer-open')}dialog.scrollTop=0;$('#drawer-close').focus();}
function saveView(){document.querySelectorAll('#app details[data-open-key]').forEach(el=>{el.open?openNodes.add(el.dataset.openKey):openNodes.delete(el.dataset.openKey)});if(lastView)viewScroll[lastView]=window.scrollY;}
function bindDual(){const input=$('#unified-q');if(input){input.oninput=e=>{unifiedQuery=e.target.value;searchPage=1;renderSearch()};$('#clear-search').onclick=()=>{unifiedQuery='';searchFilter='all';searchPage=1;input.value='';renderSearch()};renderSearch()}$('#product-category')?.addEventListener('change',e=>{productCategory=e.target.value;saveView();render()});$('#clear-category')?.addEventListener('click',()=>{productCategory='';render()});document.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{saveView();listLimits[b.dataset.more]=(listLimits[b.dataset.more]||12)+12;const y=window.scrollY;render();window.scrollTo(0,y)});document.querySelectorAll('[data-open-key]').forEach(el=>el.ontoggle=()=>{el.open?openNodes.add(el.dataset.openKey):openNodes.delete(el.dataset.openKey)});bindReviews();}
function auditPanel(){return `<section class="detail-panel"><h2>功能整理与关联检查</h2><p>${esc(fx.screening.scope)}</p><p>检查结果：没有固定只取首条的关联逻辑；旧首页摘要使用前2条限制，现改为显式完整折叠列表。保留4条有证据功能关系，没有为填满产品而新增确认关系。</p>${fx.audit.map((a,i)=>disclosure('audit-'+i,esc(a.before.join(' / '))+' → '+esc(a.action),`<p>标准功能：${esc(a.after.join('、')||'不作为同级功能')}</p><p>${esc(a.reason)}</p>`)).join('')}<a href="data/function-index.json" download>完整标准功能、别名、映射与初筛结果 ↓</a></section>`}
function oldRender(){if(!dualReady)return;const raw=location.hash.slice(1)||'products',[path,query]=raw.split('?'),[view,id]=path.split('/'),params=new URLSearchParams(query||'');currentRoute=view;const routeChanged=lastView!==raw;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(view==='product'?'products':view==='patent'?'patents':view)));if(view==='functions'&&id&&fnBy[id]){openNodes.add('parent-'+fnBy[id].parentId);openNodes.add('fn-'+id)}if(view==='product'&&params.has('candidates'))openNodes.add('pc-'+id);
 if(view==='product')$('#app').innerHTML=productDetails(id);else if(view==='functions')$('#app').innerHTML=functionsPage();else if(view==='patent'){$('#app').innerHTML=`${searchShell()}<a href="#patents">← 返回全部专利</a>${patentDetails(id,params)}`;}else if(view==='patents'){if(routeChanged&&(params.has('category')||params.has('product')))library={q:'',category:params.get('category')||'',product:params.get('product')||'',module:'',status:'',type:'',page:1};$('#app').innerHTML=searchShell()+libraryPage();bindLibrary();updateLibrary();const controls=['lib-product','lib-module','lib-type','lib-status'].map(id=>$('#'+id));const more=document.createElement('details');more.className='more-filters';more.innerHTML='<summary>更多筛选</summary>';controls[0].parentElement.append(more);controls.forEach(el=>more.append(el));if(controls.some(el=>el.value))more.open=true;}else if(view==='updates')$('#app').innerHTML=updatesPage()+auditPanel();else $('#app').innerHTML=productsPage();bindDual();lastView=raw;if(routeChanged){if(view==='functions'&&id)requestAnimationFrame(()=>document.querySelector(`[data-open-key="fn-${id}"]`)?.scrollIntoView({block:'start'}));else window.scrollTo(0,viewScroll[raw]||0)}}
document.addEventListener('click',e=>{const nav=e.target.closest('a[href^="#"]');if(nav&&!nav.hasAttribute('data-jump-claim')&&!nav.getAttribute('href').startsWith('#patent/')&&$('#patent-drawer')?.open)$('#patent-drawer').close();if(nav&&nav.getAttribute('href')===location.hash&&location.hash.startsWith('#functions/')){saveView();render();document.querySelector('[data-open-key="fn-'+location.hash.split('/')[1]+'"]')?.scrollIntoView({block:'start'});}const a=e.target.closest('a[href^="#patent/"]');if(a&&!e.metaKey&&!e.ctrlKey){e.preventDefault();const [path,q]=a.getAttribute('href').slice(1).split('?');openPatent(path.split('/')[1],new URLSearchParams(q||'').get('product')||'')}});

// Patent-first read model. Website product data is never used by scope classification.
let scopeData={},scopeBy={},typeBy={},scopeFnBy={},scopeSchemeBy={},scopeFilters={type:'',layer:'',progress:'',classification:'',legal:'',patentType:'',sourceCategory:''},scopePage=1;
const scopeSchemes=id=>scopeData.schemes.filter(s=>s.patentId===id);
const layerName=id=>scopeData.layers.find(x=>x.id===id)?.name||id;
const typeName=id=>typeBy[id]?.name||id;
const scopeIds=(rs)=>new Set(rs.map(r=>byDoc[r.id]?.applicationNumber));
const scopeCount=rs=>scopeIds(rs).size;
const oldScoped=(rs)=>rs.filter(r=>(!scopeFilters.type||r.typeIds.includes(scopeFilters.type))&&(!scopeFilters.layer||(scopeFilters.layer==='design'?r.pendingDesign:r.layers.some(l=>l.layerId===scopeFilters.layer)))&&(!scopeFilters.progress||(scopeFilters.progress==='analyzed'?r.analysisStatus==='analyzed':scopeFilters.progress==='unclassified'?!r.typeIds.length:r.analysisStatus==='pending'))&&(!scopeFilters.patentType||byDoc[r.id].patentType===scopeFilters.patentType));
function classLabel(r){return r.classificationLevel==='claims'?'权利要求依据':r.classificationLevel==='title'?'题名对象初筛 · 范围待析':r.classificationLevel==='inferred'?'摘要用途推断 · 待核实':'待分类'}
function scopeStatus(d){const c=byClaim[d.id],snap=c?.statusSnapshot;const sibling=(groups.find(g=>g.applicationNumber===d.applicationNumber)?.documentIds||[]).some(id=>id.endsWith('B'));const stage=d.patentType==='发明申请'?(sibling?'申请公布文本 · 同申请另有授权版':'申请公布文本 · 未核实后续授权'):d.patentType+'公告';return `<p class="scope-status">${esc(stage)} · ${esc(d.pubDate)}${snap?` · <a href="${esc(snap.sourceUrl)}" target="_blank" rel="noopener">第三方：${esc(snap.displayedStatus)}</a> · 查询 ${esc(snap.checkedAt)}`:' · 当前状态未核验'}${snap?.displayedStatus?.includes('Expired')?' · <strong>失效线索，按历史授权范围阅读</strong>':''}${c?.legalStatusNote?.includes('转让')?' · <strong>存在转让线索，当前权属待核验</strong>':''}<span>官方有效状态、权属及现行文本均待核验</span></p>`}
function scopeRow(r,layer='',fid=''){const d=byDoc[r.id],ss=scopeSchemes(r.id).filter(s=>(!layer||s.layers.some(l=>l.id===layer))&&(!fid||s.functionIds.includes(fid)));return `<article class="scope-record"><div class="record-heading"><a href="${docLink(d.id)}"><b>${esc(d.id)}</b> ${esc(d.title)}</a>${badge(d.patentType,'unknown')}</div>${scopeStatus(d)}<a class="sub" href="${esc(byText[r.id]?.sourceUrl||d.googlePatentsUrl)}" target="_blank" rel="noopener">原始专利文献 ↗</a>${ss.length?ss.map(s=>`<div class="scheme-line"><a href="${docLink(d.id)}">${esc(s.title)}</a><p>${esc(layer?s.layers.find(l=>l.id===layer)?.basis:s.combination)}</p><span class="sub">${esc(s.version)} · 权${s.claimNumbers.join('、')} · ${layer?esc(s.layers.find(l=>l.id===layer)?.role):'范围已初析，待复核'}</span></div>`).join(''):`<p class="pending-copy">${versionProgressHtml(r)}</p>`}<p class="sub">${esc(classLabel(r))} · 产品类型：${r.typeIds.map(t=>`<a href="#type/${t}">${esc(typeName(t))}</a>`).join('、')||'待分类'}${r.functionIds.length?' · 功能：'+r.functionIds.map(f=>`<a href="#functions/${f}">${esc(scopeFnBy[f].name)}</a>`).join('、'):''}</p></article>`}
function scopeList(rs,key,layer='',fid=''){const limit=listLimits[key]||10;return `${rs.slice(0,limit).map(r=>scopeRow(r,layer,fid)).join('')||'<p class="sub">此条件下暂无记录。可清除筛选查看完整清单。</p>'}<div class="list-count">显示 ${Math.min(limit,rs.length)} / ${rs.length} 条文献 · ${scopeCount(rs)} 个去重申请${rs.length>limit?`<button class="button" data-scope-more="${key}">加载更多</button>`:''}</div>`}
function legacyScopeControls(){return `<div class="scope-controls"><select id="scope-type" aria-label="产品类型筛选"><option value="">全部产品类型</option>${scopeData.types.map(t=>`<option value="${t.id}" ${scopeFilters.type===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><select id="scope-progress" aria-label="分析进度筛选">${[['','全部分析进度'],['analyzed','范围已初析'],['pending','范围未分析'],['unclassified','产品类型待分类']].map(([v,n])=>`<option value="${v}" ${scopeFilters.progress===v?'selected':''}>${n}</option>`).join('')}</select>${disclosure('scope-more','更多筛选',`<label>保护层面<select id="scope-layer"><option value="">全部层面／尚未判定</option>${scopeData.layers.map(l=>`<option value="${l.id}" ${scopeFilters.layer===l.id?'selected':''}>${l.name}${l.id==='design'?'（含待分析）':''}</option>`).join('')}</select></label><label>专利类型<select id="scope-patentType"><option value="">全部专利类型</option>${['发明申请','发明授权','实用新型','外观设计'].map(t=>`<option ${scopeFilters.patentType===t?'selected':''}>${t}</option>`).join('')}</select></label><p class="sub">技术层面筛选只依据已分析权利要求；外观设计可筛出待核对视图的文献。</p>`,'filter-fold')}<button id="scope-reset" class="button">清除筛选</button></div>`}

// Takeover: independent progress dimensions and complete evidence search.
let evidenceProbe={attempts:[]};
function analyzedSiblings(r){return scopeData.records.filter(x=>x.applicationNumber===r.applicationNumber&&x.analysisStatus==='analyzed')}
function applicationProgress(rs){const ids=scopeIds(rs),done=new Set(scopeData.records.filter(r=>r.analysisStatus==='analyzed').map(r=>r.applicationNumber));let analyzed=0;for(const id of ids)if(done.has(id))analyzed++;return {total:ids.size,analyzed,pending:ids.size-analyzed}}
function applicationProgressHtml(rs){const a=applicationProgress(rs);return `${a.analyzed} 个申请已有范围初析 · ${a.pending} 个申请待分析`}
function versionProgressHtml(r){const sib=analyzedSiblings(r).filter(x=>x.id!==r.id);if(sib.length)return `本版本未单独分析；同申请已有范围初析：${sib.map(x=>`<a href="${docLink(x.id)}">${esc(x.id)}</a>`).join('、')}。不将其他版本范围自动套用于本版本。`;return r.pendingDesign?'外观范围待分析：尚未核对授权图片／照片及简要说明，不从官网图推断。':`${esc(processLabel(applicationProcess(r)))}；题名或摘要仅作初筛依据。`}
function applicationProcess(r){
 const same=scopeData.records.filter(x=>x.applicationNumber===r.applicationNumber);
 if(same.some(x=>x.analysisStatus==='analyzed'))return 'analyzed';
 if(same.some(x=>byText[x.id]?.available&&(byText[x.id]?.claims?.length||byText[x.id]?.designViewsVerified)))return 'text-ready';
 const attempts=(evidenceProbe.attempts||[]).filter(x=>same.some(v=>v.id===x.id));
 if(attempts.some(x=>x.status==='available'))return 'text-ready';
 if(attempts.some(x=>x.status==='unavailable'&&x.attemptedAt))return 'source-unavailable';
 return 'unprocessed';
}
function processLabel(state){return {'analyzed':'已有范围初析','text-ready':'原文已取得待分析','source-unavailable':'已尝试，原文未取得','unprocessed':'尚未处理'}[state]||'尚未处理'}
function applicationQueue(rs){const selected=[...new Set(rs.map(r=>r.applicationNumber))];return selected.map(applicationNumber=>{const versions=scopeData.records.filter(r=>r.applicationNumber===applicationNumber),first=versions[0],status=applicationProcess(first);return {applicationNumber,status,statusLabel:processLabel(status),preferredDocumentId:(versions.find(r=>/B$/.test(r.id))||versions.find(r=>/U$/.test(r.id))||versions[0]).id,documents:versions.map(r=>({id:r.id,title:byDoc[r.id].title,sourceUrl:byText[r.id]?.sourceUrl||byDoc[r.id].googlePatentsUrl,hasClaimText:!!(byText[r.id]?.available&&byText[r.id]?.claims?.length),versionAnalyzed:r.analysisStatus==='analyzed'})),attempts:(evidenceProbe.attempts||[]).filter(x=>versions.some(r=>r.id===x.id)),legalVerification:'官方有效状态与当前权属尚待核验'}})}
function pendingQueueExport(){return applicationQueue(scoped(scopeData.records)).filter(x=>x.status!=='analyzed')}
function legalProgress(r){const c=byClaim[r.id],snap=c?.statusSnapshot;return snap?'snapshot':'unverified'}
const scoped=rs=>rs.filter(r=>(!scopeFilters.type||r.typeIds.includes(scopeFilters.type))&&(!scopeFilters.sourceCategory||byDoc[r.id].categories.includes(scopeFilters.sourceCategory))&&(!scopeFilters.layer||(scopeFilters.layer==='design'?r.pendingDesign:r.layers.some(l=>l.layerId===scopeFilters.layer)))&&(!scopeFilters.progress||(scopeFilters.progress==='analyzed'?analyzedSiblings(r).length>0:scopeFilters.progress==='unclassified'?!r.typeIds.length:scopeFilters.progress==='pending'?analyzedSiblings(r).length===0:applicationProcess(r)===scopeFilters.progress))&&(!scopeFilters.classification||(scopeFilters.classification==='unclassified'?!r.typeIds.length:r.classificationLevel===scopeFilters.classification))&&(!scopeFilters.legal||legalProgress(r)===scopeFilters.legal)&&(!scopeFilters.patentType||byDoc[r.id].patentType===scopeFilters.patentType));
function scopeControls(){const options=(items,val)=>items.map(([id,name])=>`<option value="${id}" ${val===id?'selected':''}>${esc(name)}</option>`).join('');return `<div class="scope-controls"><select id="scope-type" aria-label="产品类型筛选">${options([['','全部产品类型'],...scopeData.types.map(t=>[t.id,t.name])],scopeFilters.type)}</select><select id="scope-progress" aria-label="申请范围分析进度">${options([['','全部范围分析进度'],['analyzed','申请已有范围初析'],['pending','全部待分析申请'],['unprocessed','尚未处理'],['source-unavailable','已尝试，原文未取得'],['text-ready','原文已取得待分析']],scopeFilters.progress)}</select>${disclosure('scope-more','更多筛选',`<label>产品分类依据<select id="scope-classification">${options([['','全部分类进度'],['claims','权利要求依据'],['title','题名对象初筛'],['inferred','摘要用途推断'],['unclassified','产品类型待分类']],scopeFilters.classification)}</select></label><label>法律核验进度<select id="scope-legal">${options([['','全部法律核验进度'],['snapshot','已有第三方状态快照'],['unverified','未取得状态快照']],scopeFilters.legal)}</select></label><label>保护层面<select id="scope-layer">${options([['','全部层面／尚未判定'],...scopeData.layers.map(l=>[l.id,l.name+(l.id==='design'?'（含视图待析）':'')])],scopeFilters.layer)}</select></label><label>专利文献类型<select id="scope-patentType">${options([['','全部文献类型'],...['发明申请','发明授权','实用新型','外观设计'].map(t=>[t,t])],scopeFilters.patentType)}</select></label><p>范围进度按申请统计；同申请各版本独立保留。分类和法律核验是独立维度，第三方快照不代表已确认有效。技术层面只依据已分析方案。</p>`,'filter-fold')}<button id="scope-reset" class="button">清除筛选</button>${scopeFilters.sourceCategory?`<span class="filter-chip">原始类别：${esc(categoryName(scopeFilters.sourceCategory))}</span>`:''}</div>`}
function scopeFunctionPage(){const rs=scoped(scopeData.records),ungrouped=rs.filter(r=>!r.functionIds.length),parents=scopeData.functionParents.map(p=>{const ff=scopeData.functions.filter(f=>f.parentId===p.id&&rs.some(r=>r.functionIds.includes(f.id)&&r.analysisStatus==='analyzed'));if(!ff.length)return '';return disclosure('sfp-'+p.id,`<strong>${esc(p.name)}</strong><span class="sub">${ff.length} 个匹配功能</span>`,ff.map(f=>{const fr=rs.filter(r=>r.functionIds.includes(f.id)),ss=scopeData.schemes.filter(s=>s.functionIds.includes(f.id)&&fr.some(r=>r.id===s.patentId)),types=[...new Set(ss.flatMap(s=>s.typeIds))];return disclosure('sfn-'+f.id,`<span>${esc(f.name)}</span><span class="sub">${applicationProgressHtml(fr)}</span>`,`<div class="function-body"><p>${esc(f.definition)}</p><p class="sub">别名：${f.aliases.map(esc).join('、')}</p><p>权利要求涉及类型：${types.map(t=>`<a href="#type/${t}">${esc(typeName(t))}</a>`).join('、')||'暂无已分析依据'}</p>${scopeGroup(fr,'function-'+f.id,f.id)}</div>`,'function-leaf')}).join(''),'function-parent')}).join('');return scopeShell('functions',`<p class="scope-count">当前 ${scopeCount(rs)} 个申请 · ${applicationProgressHtml(rs)}。下方仅展示有已析方案支撑的功能；跨功能数量不可相加。</p><div class="function-tree">${parents}</div>${ungrouped.length?disclosure('function-unclassified',`功能待归类（${scopeCount(ungrouped)} 个申请／${ungrouped.length} 条文献）`,`<p class="sub">尚无充分功能归类依据，不代表无相关功能或无专利保护。搜索可命中全部这些记录；逐条范围分析后再归类。</p>${scopeList(ungrouped,'function-unclassified-list')}`):''}${!rs.length?'<div class="empty">暂无符合筛选的记录。请清除筛选。</div>':''}`)}
function globalMatches(){const q=unifiedQuery.trim().toLowerCase();if(!q)return [];const hit=s=>String(s??'').toLowerCase().includes(q),tt=scopeData.types.filter(t=>hit(t.name)),ff=scopeData.functions.filter(f=>hit(f.name)||f.aliases.some(hit)),out=[];for(const t of tt)out.push({type:'product',title:t.name,href:'#type/'+t.id,reason:'命中专利归纳产品类型',context:'不代表该类产品整体受保护'});for(const f of ff)out.push({type:'function',title:f.name,href:'#functions/'+f.id,reason:hit(f.name)?'命中标准功能':'命中功能别名',context:f.definition});for(const r of scopeData.records){const d=byDoc[r.id],direct=hit(d.id)||hit(d.title)||hit(d.applicationNumber),schemes=scopeSchemes(r.id),evidence=schemes.some(s=>[s.title,s.technicalObject,s.combination,s.keyLimits,s.difference,...s.layers.map(l=>l.basis)].some(hit)),claim=(byText[r.id]?.claims||[]).some(c=>hit(c.text)),abstract=hit(d.abstract),typeHit=r.typeIds.some(t=>tt.some(x=>x.id===t)),funcHit=r.functionIds.some(f=>ff.some(x=>x.id===f));if(direct||evidence||claim||abstract||typeHit||funcHit)out.push({type:'patent',title:d.id+' · '+d.title,href:docLink(d.id),reason:direct?'命中专利号／名称／申请号':evidence?'命中已分析范围／技术特征':claim?'命中缓存权利要求原文':typeHit?'命中产品类型':funcHit?'命中功能或别名':'命中清单摘要（仅初筛）',context:classLabel(r)+' · 类型：'+(r.typeIds.map(typeName).join('、')||'待分类')+' · 功能：'+(r.functionIds.map(f=>scopeFnBy[f].name).join('、')||'待归类'),doc:d})}return out}

function processSummary(rs){const apps=applicationQueue(rs),states=['analyzed','text-ready','source-unavailable','unprocessed'];return `<div class="process-summary" aria-label="独立处理进度">${states.map(state=>`<button type="button" class="process-pill ${scopeFilters.progress===state?'selected':''}" data-process-filter="${state}"><b>${apps.filter(a=>a.status===state).length}</b><span>${processLabel(state)}</span></button>`).join('')}</div><p class="progress-note">按申请互斥统计；“已有初析”不等于全部权利要求已分析或官方状态已核验。原文获取失败只依据真实尝试记录，未处理不冒充资料缺失。</p>`}

const claimFormLabels={method:'方法类',structure:'结构类',design:'外观类'};
function formIcon(form){const shapes={method:'<circle cx="5" cy="12" r="3"/><circle cx="25" cy="12" r="3"/><path d="M8 12h13m-4-3 4 3-4 3"/>',structure:'<rect x="2" y="5" width="10" height="14" rx="1"/><rect x="20" y="5" width="10" height="14" rx="1"/><path d="M12 12h8"/>',design:'<path d="M16 2 28 12 16 22 4 12Z"/>'};return `<svg width="32" height="24" viewBox="0 0 32 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.5">${shapes[form]||''}</svg>`;}
function schemeForms(s){if(Array.isArray(s.claimForms)&&s.claimForms.length)return s.claimForms.map(f=>typeof f==='string'?{id:f,claimNumbers:s.claimFormNumbers?.[f]||s.claimNumbers}:f);const structural=['CN109115176B','CN104459729B','CN209389698U','CN205582976U'];const methods=['CN116719053B','CN112633092B','CN116501050B','CN116339340B','CN112902931B','CN113093256B','CN106326106B'];return structural.includes(s.patentId)||methods.includes(s.patentId)?[{id:structural.includes(s.patentId)?'structure':'method',claimNumbers:s.claimNumbers}]:[];}
function coveragePanel(rs){const a=applicationProgress(rs);return disclosure('scope-coverage',`资料覆盖 · ${a.analyzed} / ${a.total} 个申请已有初析，${a.pending} 个尚未分析`,`${processSummary(rs)}<p>仅已核权利要求进入下方范围图谱。尚未分析不等于没有保护，也不等于原文缺失；所有文献版本完整保留。</p><p><a href="#patents">查看全量资料、筛选进度及导出待补清单 →</a></p><div class="downloads"><a href="data/full-portfolio-evidence-request.csv" download>下载全文资料补充清单（全部申请） ↓</a><a href="data/application-evidence-queue.json" download>下载全量申请队列 JSON ↓</a></div><p class="sub">这是全部申请的统一补充与核对清单，并非全部资料缺失；按进度筛选后批量补充，无需逐条手工录入。</p>`,'coverage-fold');}
function scopeShell(view,body){const rs=scoped(scopeData.records);return `<section class="scope-head"><div><h1>从专利范围，看产品与技术。</h1><p>权利要求 → 产品类型／功能 → 方法、结构与外观</p></div><div class="segmented"><a href="#products" class="${view==='products'?'selected':''}">按产品类型</a><a href="#functions" class="${view==='functions'?'selected':''}">按功能</a></div></section>${searchShell()}${scopeControls()}${coveragePanel(rs)}<p class="sub">外观范围仅依据已核授权视图；目前未完成该类分析，不以官网图片或实用新型附图替代。</p>${body}`;}
function scopeGroup(rs,key,fid=''){const ss=scopeData.schemes.filter(s=>rs.some(r=>r.id===s.patentId&&r.analysisStatus==='analyzed')&&(!fid||s.functionIds.includes(fid))&&(!scopeFilters.layer||s.layers.some(l=>l.id===scopeFilters.layer)));return `<div class="claim-form-grid">${Object.entries(claimFormLabels).map(([form,label])=>{const matched=ss.filter(s=>schemeForms(s).some(f=>f.id===form));return `<section class="claim-form ${form}"><h3><span class="form-symbol">${formIcon(form)}</span>${label}<small>${matched.length} 项方案</small></h3>${matched.length?matched.map(s=>{const f=schemeForms(s).find(f=>f.id===form),nums=f.claimNumbers||s.claimNumbers,d=byDoc[s.patentId];return `<article class="scope-brief"><a href="${docLink(s.patentId)}"><b>${esc(s.title)}</b></a><p class="scope-combination"><strong>组合：</strong>${esc(s.combination)}</p><p class="scope-limits"><strong>限定：</strong>${esc(s.keyLimits)}</p><a class="citation" href="${docLink(s.patentId)}">${esc(s.patentId)} · ${esc(d.title)}<br>权 ${nums.join('、')}</a><div class="scope-tags">${f.label?`<span>${esc(f.label)}</span>`:form==='structure'?'<span>系统／装置或部件组合；具体客体见原文</span>':''}${s.layers.filter(l=>!scopeFilters.layer||l.id===scopeFilters.layer).map(l=>`<span>${esc(layerName(l.id))} · ${esc(l.role)}</span>`).join('')}</div></article>`}).slice(0,3).join('')+(matched.length>3?disclosure(key+'-'+form+'-more',`展开其余 ${matched.length-3} 项及引用`,matched.slice(3).map(s=>`<article class="scope-brief"><a href="${docLink(s.patentId)}"><b>${esc(s.title)}</b></a><p class="scope-combination"><strong>组合：</strong>${esc(s.combination)}</p><p class="scope-limits"><strong>限定：</strong>${esc(s.keyLimits)}</p><a class="citation" href="${docLink(s.patentId)}">${esc(s.patentId)} · ${esc(byDoc[s.patentId].title)} · 权 ${(schemeForms(s).find(f=>f.id===form).claimNumbers||s.claimNumbers).join('、')}</a></article>`).join('')):''):`<p class="sub">${form==='design'?'无已核视图。':'当前已析证据尚未建立本类范围；不推定无相关保护。'}</p>`}</section>`}).join('')}</div><p class="sub form-note">符号仅表示客体类别，不是专利附图或具体结构示意；每项范围独立，不合并为共同保护范围。</p>`;}
let typeCardsInitialized=false;
function typeCard(t,rs){const ss=scopeData.schemes.filter(s=>s.typeIds.includes(t.id)&&rs.some(r=>r.id===s.patentId));const counts=Object.entries(claimFormLabels).map(([id,name])=>`${name} ${ss.filter(s=>schemeForms(s).some(f=>f.id===id)).length}`).join(' · ');return `<article class="type-card" id="type-${t.id}"><div class="type-card-head"><div class="type-intro"><h2><a href="#type/${t.id}">${esc(t.name)}</a></h2><p class="sub">${applicationProgressHtml(rs)} · ${counts}</p></div></div>${disclosure('type-range-'+t.id,'查看范围与引用专利',scopeGroup(rs,'type-'+t.id))}</article>`;}
function typesPage(selected=''){let rs=scoped(scopeData.records);if(selected)rs=rs.filter(r=>r.typeIds.includes(selected));const ts=scopeData.types.filter(t=>(!selected||t.id===selected)&&(!scopeFilters.type||t.id===scopeFilters.type)&&rs.some(r=>r.typeIds.includes(t.id)&&r.analysisStatus==='analyzed')).sort((a,b)=>Number(rs.some(r=>r.typeIds.includes(b.id)&&r.analysisStatus==='analyzed'))-Number(rs.some(r=>r.typeIds.includes(a.id)&&r.analysisStatus==='analyzed')));const pending=rs.filter(r=>!r.typeIds.length);if(!typeCardsInitialized&&ts.length){openNodes.add('type-range-'+ts[0].id);typeCardsInitialized=true;}if(selected)openNodes.add('type-range-'+selected);return scopeShell('products',`${selected?'<a class="back" href="#products" data-clear-scope>← 返回全部产品类型</a>':''}<p class="scope-count">当前 ${rs.length} 条文献／${scopeCount(rs)} 个申请 · ${applicationProgressHtml(rs)}。跨类型、跨层面不可相加。</p>${ts.map(t=>typeCard(t,rs.filter(r=>r.typeIds.includes(t.id)))).join('')}${!selected?`<p class="sub">${scopeCount(pending)} 个申请暂无产品类型归类；<a href="#patents">在全量资料中查看</a>。这里只展示已有范围依据的类型。</p>`:''}${!ts.length&&!pending.length?'<div class="empty">暂无符合筛选的记录。请清除筛选。</div>':''}`)}
function legacyScopeFunctionPage(){const rs=scoped(scopeData.records);return scopeShell('functions',`<p class="scope-count">功能从已分析专利的技术目的与步骤归纳；同词命中的未分析文献单列候选。产品官网不参与分类。已析与候选按文献版本分开，涉及的申请可重叠。</p><div class="function-tree">${scopeData.functionParents.map(p=>{const ff=scopeData.functions.filter(f=>f.parentId===p.id);return disclosure('sfp-'+p.id,`<strong>${esc(p.name)}</strong><span class="sub">${ff.length} 个功能</span>`,ff.map(f=>{const fr=rs.filter(r=>r.functionIds.includes(f.id));const ss=scopeData.schemes.filter(s=>s.functionIds.includes(f.id)&&fr.some(r=>r.id===s.patentId));const types=[...new Set(ss.flatMap(s=>s.typeIds))];return disclosure('sfn-'+f.id,`<span>${esc(f.name)}</span><span class="sub">${scopeCount(fr.filter(r=>r.analysisStatus==='analyzed'))} 已析申请 · ${scopeCount(fr.filter(r=>r.analysisStatus!=='analyzed'))} 候选申请</span>`,`<div class="function-body"><p>${esc(f.definition)}</p><p class="sub">别名：${f.aliases.map(esc).join('、')}</p><p>权利要求涉及类型：${types.map(t=>`<a href="#type/${t}">${esc(typeName(t))}</a>`).join('、')||'暂无已分析依据'}</p>${scopeGroup(fr,'function-'+f.id,f.id)}</div>`,'function-leaf')}).join(''),'function-parent')}).join('')}</div>`)}
function scopeLibrary(){const rs=scoped(scopeData.records),limit=scopePage*20;return scopeShell('library',`<h2>全部专利文献</h2><p class="sub">原始${docs.length}条文献、${scopeCount(scopeData.records)}个申请全部保留。国际专利族未归组。A/B版本分别存档，同申请不重复计数。</p><div class="downloads"><span class="sub">Excel 原件不公开提供</span><a href="data/scope-index.json" download>范围分析与分类依据 ↓</a><button id="scope-export" class="linkbutton">导出当前筛选</button><button id="pending-queue-export" class="linkbutton">导出待分析／待补材料清单</button></div><p class="scope-count">${rs.length} 条文献／${scopeCount(rs)} 个申请 · ${applicationProgressHtml(rs)}</p><div class="scope-library">${rs.slice(0,limit).map(r=>scopeRow(r)).join('')||'<div class="empty">无匹配记录。请清除筛选。</div>'}</div><div class="list-count">已显示 ${Math.min(limit,rs.length)} / ${rs.length}${rs.length>limit?'<button id="scope-library-more" class="button">加载更多</button>':''}</div>`)}
function legacyScopeGlobalMatches(){const q=unifiedQuery.trim().toLowerCase();if(!q)return [];const hit=s=>String(s).toLowerCase().includes(q),tt=scopeData.types.filter(t=>hit(t.name)),ff=scopeData.functions.filter(f=>hit(f.name)||f.aliases.some(hit)),out=[];for(const t of tt)out.push({type:'product',title:t.name,href:'#type/'+t.id,reason:'命中专利归纳产品类型',context:'不代表该类产品整体受保护'});for(const f of ff)out.push({type:'function',title:f.name,href:'#functions/'+f.id,reason:hit(f.name)?'命中标准功能':'命中功能别名',context:f.definition});for(const r of scopeData.records){const d=byDoc[r.id],direct=hit(d.id)||hit(d.title)||hit(d.applicationNumber),typeHit=r.typeIds.some(t=>tt.some(x=>x.id===t)),funcHit=r.functionIds.some(f=>ff.some(x=>x.id===f));if(direct||typeHit||funcHit)out.push({type:'patent',title:d.id+' · '+d.title,href:docLink(d.id),reason:direct?'命中专利号／名称／申请号':typeHit?'命中产品类型':'命中功能或别名',context:classLabel(r)+' · 类型：'+(r.typeIds.map(typeName).join('、')||'待分类')+' · 功能：'+(r.functionIds.map(f=>scopeFnBy[f].name).join('、')||'待分析'),doc:d})}return out}
function renderSearch(){const box=$('#unified-results');if(!box)return;const rs=globalMatches().filter(r=>searchFilter==='all'||r.type===searchFilter),limit=searchPage*12;box.innerHTML=!unifiedQuery.trim()?'':`<div class="search-results"><div class="section-title"><h3>全量搜索 · ${rs.length} 个匹配项</h3><select id="search-kind" aria-label="搜索结果类型">${[['all','全部'],['product','产品类型'],['function','功能'],['patent','专利文献']].map(([v,n])=>`<option value="${v}" ${searchFilter===v?'selected':''}>${n}</option>`).join('')}</select></div><p class="sub">搜索覆盖全部文献，独立于下方浏览筛选；折叠与加载数量不限制搜索。</p>${rs.slice(0,limit).map(r=>`<article class="search-hit"><span class="sub">${{product:'产品类型',function:'功能',patent:'专利文献'}[r.type]}</span><a href="${r.href}">${esc(r.title)}</a><p>${esc(r.reason)} · ${esc(r.context)}</p>${r.doc?scopeStatus(r.doc)+`<div class="function-chips">${scopeBy[r.doc.id].typeIds.map(t=>`<a href="#type/${t}">${esc(typeName(t))}</a>`).join('')}${scopeBy[r.doc.id].functionIds.map(f=>`<a href="#functions/${f}">${esc(scopeFnBy[f].name)}</a>`).join('')}</div>`:''}</article>`).join('')||'<div class="empty">未找到匹配项。可更换专利号、产品类型或功能别名。</div>'}<div class="list-count">已显示 ${Math.min(limit,rs.length)} / ${rs.length}${rs.length>limit?'<button id="search-more" class="button">加载更多</button>':''}</div></div>`;$('#search-kind')?.addEventListener('change',e=>{searchFilter=e.target.value;searchPage=1;renderSearch()});$('#search-more')?.addEventListener('click',()=>{searchPage++;renderSearch()})}
function schemeDetails(s){return `<section class="detail-panel scheme-detail"><h2>${esc(s.title)}</h2><p class="sub">${esc(s.version)} · 权利要求 ${s.claimNumbers.join('、')} · 解释整理 ${s.analysisDate}</p><p class="scope-warning">${esc(s.documentBasis)}${s.currentValidity.includes('历史')?'；'+esc(s.currentValidity):''}</p><dl class="scope-dl"><dt>技术对象</dt><dd>${esc(s.technicalObject)}</dd><dt>必要组合及特征关系</dt><dd>${esc(s.combination)}</dd><dt>关键限制</dt><dd>${esc(s.keyLimits)}</dd><dt>与其他方案的区别</dt><dd>${esc(s.difference)}</dd><dt>产品类型归纳</dt><dd>${s.typeIds.map(t=>`<a href="#type/${t}">${esc(typeName(t))}</a>`).join('、')} · ${esc(s.classificationBasis)}</dd><dt>功能依据</dt><dd>${s.functionIds.map(f=>`<a href="#functions/${f}">${esc(scopeFnBy[f].name)}</a>`).join('、')}；依据上述权利要求的对象、步骤和输出，不依官网宣传。</dd></dl>${s.layers.map(l=>`<p><b>${esc(layerName(l.id))}</b> · ${esc(l.role)}<br>${esc(l.basis)} <span class="sub">（权${l.claimNumbers.join('、')}）</span></p>`).join('')}<p><a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">对应文献依据 ↗</a> · <a href="#claim-${s.patentId}-${s.claimNumbers[0]}" data-jump-claim="claim-${s.patentId}-${s.claimNumbers[0]}">展开对应权利要求 ↓</a></p></section>`}
function patentDetails(id,params){const r=scopeBy[id];if(!r)return legacyPatentDetails(id,params);const ss=scopeSchemes(id);const block=`<h1 style="font-size:24px">${esc(byDoc[id].title)}</h1>${scopeStatus(byDoc[id])}<section class="detail-panel"><h2>从专利归纳的分类依据</h2><p>${esc(classLabel(r))} · ${r.analysisStatus==='analyzed'?'范围已初析，待IP复核':'范围尚未分析'}</p>${r.classificationEvidence.map(e=>`<p><b>${esc(typeName(e.typeId))}</b>：${esc(e.source)}${e.quote?' · '+esc(e.quote):''}${e.matchedTerms?' · 命中 '+e.matchedTerms.map(esc).join('、'):''}</p>`).join('')||'<p>暂无足够依据，保留待分类。</p>'}<p class="sub">产品类型归纳、范围解释和具体型号实施是不同结论；本分类不认定任何商品型号已实施。</p></section>${ss.map(schemeDetails).join('')}${r.pendingDesign?'<section class="detail-panel"><h2>外观设计范围 · 尚未分析</h2><p>尚未核对授权图片或照片、简要说明、色彩请求及是否局部设计；不依据题名或官网图片填写形状、图案、色彩范围。</p><p>实用新型附图不能替代本件外观授权视图。</p></section>':''}`;let legacy=legacyPatentDetails(id,params);legacy=legacy.replace(/<h1[^>]*>[\s\S]*?<\/h1>/,'');legacy=legacy.replace('<h2>产品关联证据</h2>','<h2>官网型号辅助线索</h2><p class="rule">官网功能仅辅助理解，不参与上述范围划定；功能相符不等于型号实施已确认。</p>');return block+legacy}
function scopeUpdates(){const aa=scopeData.records.filter(r=>r.analysisStatus==='analyzed');return `<h1>范围分析与更新记录</h1><p>静态画像／手动更新。原清单截至2026-10-30，证据核对日期按文献分别保存；刷新不改变核验日期。</p><section class="detail-panel"><h2>本版实际覆盖</h2><p>${docs.length}条文献／${scopeCount(scopeData.records)}个申请全部保留；${aa.length}件授权文献范围初析，${scopeData.schemes.length}项分别解释的技术方案，${scopeData.records.filter(r=>!r.typeIds.length).length}条产品类型待分类。</p><p>${applicationProgressHtml(scopeData.records)}；已缓存${Object.values(byText).reduce((n,t)=>n+(t.claims||[]).length,0)}项权利要求。其他文献仅作对象／用途候选，不计作范围分析。</p><p>${scopeData.designGap}</p><p>原文获取与分析进度按实际记录单列；“尚未处理”不代表资料无法取得。第三方状态线索不等同于官方有效状态核验，亦非具体型号实施证明。</p></section><section class="detail-panel"><h2>本次修正</h2><ul>${scopeData.corrections.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>功能调整：原“定位测深”等宽泛功能改为“定位测深时延处理”；点云采集、雷达标定、点云转换与道路要素提取分别解释；旧版函数分类文件完整保留。</p></section>${disclosure('history-updates','展开全部历史记录与原始资料',updatesPage()+auditPanel())}<div class="downloads"><a href="data/scope-index.json" download>本版范围及分类数据 ↓</a><a href="data/portfolio.json" download>全部原始文献 ↓</a><a href="data/claims.json" download>保留的既有分析 ↓</a><a href="#models">官网型号辅助资料 →</a></div>`}
function bindScope(){bindDual();document.querySelectorAll('[data-process-filter]').forEach(b=>b.onclick=()=>{saveView();scopeFilters.progress=b.dataset.processFilter;scopePage=1;render()});$('#pending-queue-export')?.addEventListener('click',()=>download('chcnav-pending-application-queue.json',pendingQueueExport()));for(const key of ['type','layer','progress','classification','legal','patentType'])$('#scope-'+key)?.addEventListener('change',e=>{saveView();scopeFilters[key]=e.target.value;scopePage=1;render()});$('#scope-reset')?.addEventListener('click',()=>{scopeFilters={type:'',layer:'',progress:'',classification:'',legal:'',patentType:'',sourceCategory:''};scopePage=1;render()});document.querySelectorAll('[data-scope-more]').forEach(b=>b.onclick=()=>{saveView();listLimits[b.dataset.scopeMore]=(listLimits[b.dataset.scopeMore]||10)+10;const y=window.scrollY;render();window.scrollTo(0,y)});$('#scope-library-more')?.addEventListener('click',()=>{saveView();scopePage++;const y=window.scrollY;render();window.scrollTo(0,y)});$('#scope-export')?.addEventListener('click',()=>download('patent-scope-filter.json',scoped(scopeData.records).map(r=>({document:byDoc[r.id],scope:r,schemes:scopeSchemes(r.id)}))))}
function render(){if(currentReady&&currentRender())return;if(!dualReady||!scopeData.records)return;const raw=location.hash.slice(1)||'products',[path,q]=raw.split('?'),[view,id]=path.split('/'),params=new URLSearchParams(q||''),changed=raw!==lastView;currentRoute=view;if(changed&&view==='patents'&&params.has('category'))scopeFilters.sourceCategory=params.get('category');if(changed&&view==='type')scopeFilters={type:id,layer:'',progress:'',classification:'',legal:'',patentType:'',sourceCategory:''};if(changed&&view==='functions'&&id&&scopeFnBy[id])scopeFilters={type:'',layer:'',progress:'',classification:'',legal:'',patentType:'',sourceCategory:''};if(view==='functions'&&id&&scopeFnBy[id]){openNodes.add('sfp-'+scopeFnBy[id].parentId);openNodes.add('sfn-'+id)}document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(view==='type'?'products':view==='patent'?'patents':view)));
 if(view==='functions')$('#app').innerHTML=scopeFunctionPage();else if(view==='type')$('#app').innerHTML=typesPage(id);else if(view==='patents')$('#app').innerHTML=scopeLibrary();else if(view==='patent')$('#app').innerHTML=patentDetails(id,params);else if(view==='updates')$('#app').innerHTML=scopeUpdates();else if(view==='models')$('#app').innerHTML='<h1>官网型号辅助资料</h1><p class="scope-warning">产品示例，非已确认实施该专利的型号。官网照片不作为权利范围依据。</p>'+models.map(m=>`<section class="aux-model">${photo(m)}<div><h2>${esc(m.name)}</h2><p>${esc(m.purpose)}</p><p>产品示例，非已确认实施该专利的型号。</p><a href="#product/${m.id}">查看保留的型号资料与历史线索 →</a></div></section>`).join('');else if(view==='product')$('#app').innerHTML='<p class="scope-warning">官网型号辅助资料：产品示例，非已确认实施该专利的型号；旧版候选数量不代表保护范围。</p>'+productDetails(id);else $('#app').innerHTML=typesPage();bindScope();lastView=raw;if(changed){if(view==='functions'&&id&&scopeFnBy[id])requestAnimationFrame(()=>document.querySelector(`[data-open-key="sfn-${id}"]`)?.scrollIntoView({block:'start'}));else window.scrollTo(0,viewScroll[raw]||0)}}
document.addEventListener('click',e=>{if(e.target.closest('[data-clear-scope]'))scopeFilters={type:'',layer:'',progress:'',classification:'',legal:'',patentType:'',sourceCategory:''};const same=e.target.closest('a[href^="#functions/"]');if(same&&same.getAttribute('href')===location.hash){const id=location.hash.split('/')[1];if(scopeFnBy[id]){openNodes.add('sfp-'+scopeFnBy[id].parentId);openNodes.add('sfn-'+id);render();document.querySelector('[data-open-key="sfn-'+id+'"]')?.scrollIntoView({block:'start'})}}const j=e.target.closest('[data-jump-claim]');if(j){e.preventDefault();const el=$('#patent-drawer')?.querySelector('[id="'+j.dataset.jumpClaim+'"]')||document.getElementById(j.dataset.jumpClaim);if(el){el.open=true;el.scrollIntoView({block:'start'})}}});

