// Excel-backed read model. Original v13 records and analyses remain immutable and available.
let currentReady=false,currentDocs=[],currentAnalyses=[],currentTexts={},currentById={},currentByApp={},currentBaseline={},currentTaxonomy={},currentSearchIndex={},currentQuery='',currentFilter={status:'',form:'',product:''},currentPage=1,currentGroupPages={},currentLoadIssue='';
const currentArray=x=>Array.isArray(x)?x:Array.isArray(x?.records)?x.records:[];
const currentStrings=x=>Array.isArray(x)?x.map(v=>typeof v==='string'?v:v?.text||v?.label||v?.name||'').filter(Boolean):x?[String(x)]:[];
const currentName=x=>typeof x==='string'?x:x?.name||x?.label||x?.id||'';
const currentType=a=>currentName(a?.productType)||'未归类';
function currentFunctions(a){const raw=Array.isArray(a?.functions)?a.functions:[a?.function].filter(Boolean);return [...new Set(raw.map(currentName).map(name=>currentTaxonomy.aliases?.[name]||(currentTaxonomy.functions||[]).find(f=>f.name===name||f.id===name||f.aliases?.includes(name))?.name||name).filter(Boolean))];}
const currentDone=a=>a?.status==='analyzed';
const currentDesign=a=>a?.status==='design-reviewed';
function currentAnalysis(d){return currentAnalyses.find(a=>a.id===d.id)||currentByApp[d.applicationNumber]||null;}
function currentStats(ds=currentDocs){const apps=new Map(ds.map(d=>[d.applicationNumber,d]));let technical=0,design=0,pending=0;for(const d of apps.values()){const a=currentAnalysis(d);if(currentDone(a))technical++;else if(currentDesign(a))design++;else pending++;}return {total:apps.size,technical,design,pending};}
function currentInit(portfolio,analysis,textsData,baselineData,taxonomy){const ds=currentArray(portfolio),aa=currentArray(analysis);if(!ds.length||!aa.length||ds.some(d=>!d.id||!d.applicationNumber)||aa.some(a=>!a.id||!a.applicationNumber))throw Error('新资料索引不完整');const ids=new Set(ds.map(d=>d.id));if(ids.size!==ds.length||aa.some(a=>!ids.has(a.id)))throw Error('新资料文献关联不一致');currentDocs=ds;currentAnalyses=aa;currentById=Object.fromEntries(ds.map(d=>[d.id,d]));currentTexts=Object.fromEntries(currentArray(textsData).map(t=>[t.id,t]));currentBaseline=baselineData||{};currentTaxonomy=taxonomy||{};currentByApp={};for(const a of aa){const prev=currentByApp[a.applicationNumber];if(!prev||currentDone(a)&&!currentDone(prev)||/B$/.test(a.id)&&!/B$/.test(prev.id))currentByApp[a.applicationNumber]=a;}currentSearchIndex=Object.fromEntries(ds.map(d=>[d.id,JSON.stringify([d.id,d.applicationNumber,d.title,d.abstract,currentAnalysis(d),currentTexts[d.id]?.claims]).toLowerCase()]));currentReady=true;}
function currentFiltered(){const q=currentQuery.trim().toLowerCase();return currentDocs.filter(d=>{const a=currentAnalysis(d);return (!currentFilter.product||primaryMap[d.applicationNumber]?.primaryProductId===currentFilter.product)&&(!q||currentSearchIndex[d.id].includes(q))&&(!currentFilter.status||(currentFilter.status==='technical'?currentDone(a):currentFilter.status==='design'?currentDesign(a):!currentDone(a)&&!currentDesign(a)))&&(!currentFilter.form||(a?.formGroups||[]).some(g=>g.form===currentFilter.form));});}
function currentSource(d){return d.googlePatentsUrl||d.sourceUrl||`https://patents.google.com/patent/${encodeURIComponent(d.id)}/zh`;}
function currentLabel(a){return currentDone(a)?(a.analysisCompleteness==='limited'?'技术初析 · 原文存在局部缺口':'技术权利要求初析'):currentDesign(a)?'外观资料解读 · 非完整范围':'资料已入库 · 未纳入本批分析';}
function currentControls(){return `<div class="unified-search"><label class="sr-only" for="current-q">搜索全部文献、权利要求与分析</label><input id="current-q" type="search" value="${esc(currentQuery)}" placeholder="搜索专利号、产品类型、功能、权利要求特征"><button id="current-clear" class="button">清除</button></div><div class="current-filters"><label>主产品类型<select id="current-product"><option value="">全部产品类型</option>${primaryData.categories.map(c=>`<option value="${c.id}" ${currentFilter.product===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>资料类型<select id="current-status">${[['','全部资料'],['technical','技术权利要求初析'],['design','外观资料解读'],['pending','其它已入库资料']].filter(([v])=>v!=='pending'||currentStats().pending>0).map(([v,t])=>`<option value="${v}" ${currentFilter.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="reader-legacy-form">权利要求客体<select id="current-form">${[['','全部客体'],['method','方法类'],['structure','结构类'],['design','外观类']].map(([v,t])=>`<option value="${v}" ${currentFilter.form===v?'selected':''}>${t}</option>`).join('')}</select></label><a href="#patents">全量文献与版本 →</a></div>`;}
function currentCoverage(){const s=currentStats(),limited=new Set(currentAnalyses.filter(a=>currentDone(a)&&a.analysisCompleteness==='limited').map(a=>a.applicationNumber)).size;return disclosure('current-coverage',`资料覆盖：${currentDocs.length} 条文献 / ${s.total} 个申请 · 技术初析 ${s.technical}${limited?'（局部缺口 '+limited+'）':''} · 外观资料解读 ${s.design}${s.pending?' · 其它 '+s.pending:''}`,`<p>技术初析依据用户提供的权利要求文本；外观资料解读依据简要说明与所提供图片，不能替代完整授权视图分析。公开申请只展示公开方案，不等于已取得授权。</p><p>法律有效性、当前权属、完整公式及版本差异仍须按具体来源核验。同申请版本保留，不重复计为申请；各主产品申请数可以相加，产品内跨功能及客体不可相加。</p><p class="sub">${pdfIndex?`已关联 ${pdfIndex.counts.matched} 份 PDF，按完整公开号区分文献版本。文件入库不表示已完成内容或法律核验。`:pdfLoadIssue?'PDF 索引暂未载入，请刷新重试。':'此批资料尚无 PDF 索引。'}</p><div class="downloads"><a href="data/pdf-index.json" download>PDF 对应清单 ↓</a><a href="data/portfolio-current.json" download>本次文献清单 ↓</a><a href="data/full-analysis.json" download>本次分析与限制 ↓</a><a href="data/product-portraits.json" download>主产品边界与逐申请归属 ↓</a><a href="data/claim-texts-current.json" download>本次权利要求文本 ↓</a><a href="data/baseline-current.json" download>来源与覆盖口径 ↓</a><a href="data/evidence-review-list.csv" download>下载需原件核对的具体清单 ↓</a><span class="sub">Excel 原件不公开提供</span></div><p class="sub">本次完整 Excel 不公开下载；仅提供必要的文献、分析和文本记录。图片懒加载，原文按文献展开。</p>`,'coverage-fold');}
function currentHeader(view){return `<section class="scope-head reader-page-head"><div><h1>华测导航（CHCNAV）· 专利画像</h1><p>按产品类型浏览，每个申请一个主归属；产品内查看功能主题及多篇专利的路径差异。</p></div></section>${currentCoverage()}${currentControls()}`;}
function currentVisual(g){const steps=currentStrings(g.steps);if(!steps.length||g.form==='design')return '';const directed=g.form==='method'&&['flow','process','workflow','sequence'].includes(g.diagramKind);return `<div class="current-step-list" aria-label="${directed?'依据分析记录的步骤流程':'分析部件或步骤摘要'}">${steps.slice(0,5).map((t,i)=>`${directed&&i?'<i class="current-flow-arrow" aria-hidden="true"><svg width="16" height="12" viewBox="0 0 16 12" fill="none" stroke="currentColor"><path d="M1 6h13m-4-4 4 4-4 4"/></svg></i>':''}<span><small>${i+1}</small>${esc(t)}</span>`).join('')}</div><p class="sub current-visual-note">${directed?'按已分析步骤整理的流程摘要':'按分析记录整理的部件／步骤摘要，顺序不额外断言技术依赖'}，非专利原图。</p>`;}
function currentForm(g,a,compact=true){const nums=g.claimNumbers||g.evidenceClaimNumbers||[];return `<section class="current-form-block ${esc(g.form)}"><h4>${formIcon(g.form)}${esc(g.label||claimFormLabels[g.form]||'权利要求方案')} <span class="sub">${g.form==='design'?'资料解读':nums.length?'权 '+nums.join('、'):'具体编号见分析依据'}</span></h4><p class="current-combination ${compact?'clamped':''}">${esc(currentStrings(g.summary).join('；'))}</p>${currentVisual(g)}${currentStrings(g.limitations).length?`<p class="current-limit ${compact?'clamped':''}"><b>限制：</b>${esc(currentStrings(g.limitations).join('；'))}</p>`:''}</section>`;}
function currentKnownStatus(id){const snap=byClaim[id]?.statusSnapshot;if(!snap)return '<span class="sub">当前法律状态未核验</span>';const expired=/expired|lapsed|withdrawn|revoked|ceased/i.test(snap.displayedStatus||'');return `<span class="${expired?'badge candidate':'sub'}">${expired?'历史失效线索':'第三方状态'}：${esc(snap.displayedStatus)} · ${esc(displayDate(snap.checkedAt))}，未官方核验</span>`;}
function currentBrief(a,form=null){const d=currentById[a.id];return `<article class="current-brief"><div class="record-heading"><a href="${docLink(a.id)}"><b>${esc(a.id)}</b> ${esc(d.title)}</a><span class="badge unknown">${esc(d.patentType||'')}${/A$/.test(a.id)?' · 公开方案':''}</span></div><p class="sub">${esc(currentLabel(a))} · ${esc(currentType(a))}</p><p class="current-status-note">${currentKnownStatus(a.id)}</p><div class="current-form-mini">${(a.formGroups||[]).filter(g=>!form||g.form===form).map(g=>currentForm(g,a,true)).join('')||'<p class="sub">本条未提供可展示的范围组合，请查看来源及限制。</p>'}</div>${currentDesign(a)?currentDesignImage(a,d):''}<a class="sub" href="${docLink(a.id)}">完整分析、从属限定与原文 →</a></article>`;}
function currentFamily(a,view){if(view!=='functions'&&primaryFor(a))return primaryFor(a).name;const key=view==='functions'?'functionFamily':'productFamily',map=view==='functions'?currentTaxonomy.functionFamilies:currentTaxonomy.productFamilies;return map?.[a[key]]||currentName(a[key])||'未归类';}
function legacyCurrentGroups(ds,view){
 const matching=new Set(ds.map(d=>d.applicationNumber)),families=new Map();
 for(const a of currentAnalyses){if(!matching.has(a.applicationNumber))continue;const family=currentFamily(a,view);if(!families.has(family))families.set(family,new Map());families.get(family).set(a.applicationNumber,a);}
 const order=Object.values(view==='functions'?currentTaxonomy.functionFamilies||{}:currentTaxonomy.productFamilies||{});
 const entries=[...families].sort((a,b)=>(order.indexOf(a[0])<0?999:order.indexOf(a[0]))-(order.indexOf(b[0])<0?999:order.indexOf(b[0]))),pageEntries=entries.slice(0,currentPage*16);
 return `<p class="scope-count">匹配 ${ds.length} 条文献 / ${new Set(ds.map(d=>d.applicationNumber)).size} 个申请 · ${entries.length} 个主分类。同一申请可有多类权利要求，各类数量不相加。外观按简要说明用途关联，不表示保护技术功能。</p><div class="current-group-list">${pageEntries.map(([family,map])=>{
  const key='current-family-'+view+'-'+encodeURIComponent(family),all=[...map.values()],forms=Object.entries(claimFormLabels).filter(([f])=>!currentFilter.form||currentFilter.form===f);
  const countLine=forms.map(([f,l])=>l+' '+all.filter(a=>(a.formGroups||[]).some(g=>g.form===f)).length).join(' · ');
  return disclosure(key,`<strong>${esc(family)}</strong><span class="sub">${all.length} 个申请 · ${countLine}</span>`,`<div class="current-family-forms">${forms.map(([f,label])=>{
    const items=all.filter(a=>(a.formGroups||[]).some(g=>g.form===f)),moreKey=key+'-'+f,limit=currentGroupPages[moreKey]||3;
    return `<section class="current-family-form ${f}"><h3>${formIcon(f)} ${label} <span class="sub">${items.length}</span></h3>${items.slice(0,limit).map(a=>currentBrief(a,f)).join('')||'<p class="sub">本组没有该类已核资料。</p>'}<div class="list-count">${items.length?`已显示 ${Math.min(limit,items.length)} / ${items.length}`:''}${items.length>limit?`<button class="button" data-current-more="${esc(moreKey)}">展开更多</button>`:''}</div></section>`;
  }).join('')}</div>`,'current-group');
 }).join('')||'<div class="empty">没有符合条件的分析条目。全量文献入口仍保留全部版本。</div>'}</div>${entries.length>pageEntries.length?'<button class="button" id="current-more-groups">加载更多分类</button>':''}`;
}
let primaryData={categories:[],mappings:[]},primaryById={},primaryMap={};
function initPrimaryProducts(data){
 if(!data?.categories?.length||data.mappings?.length!==currentAnalyses.length)throw Error('主产品目录不完整');
 primaryData=data;primaryById=Object.fromEntries(data.categories.map(c=>[c.id,c]));primaryMap=Object.fromEntries(data.mappings.map(m=>[m.applicationNumber,m]));
 if(Object.keys(primaryMap).length!==currentAnalyses.length||currentAnalyses.some(a=>!primaryById[primaryMap[a.applicationNumber]?.primaryProductId]))throw Error('主产品必须唯一且覆盖全部申请');
 for(const d of currentDocs){const c=primaryById[primaryMap[d.applicationNumber].primaryProductId];currentSearchIndex[d.id]+=' '+c.name;}
}
function primaryFor(a){return primaryById[primaryMap[a?.applicationNumber]?.primaryProductId];}
function primaryBoundary(name){const c=primaryData.categories.find(x=>x.name===name);return c?`<div class="product-boundary"><p><b>纳入：</b>${esc(c.include)}</p><p><b>另归其他类型：</b>${esc(c.exclude)}</p></div>`:'';}
function primaryDetail(a){const c=primaryFor(a),m=primaryMap[a?.applicationNumber];return c?`<section class="detail-panel"><h3>主产品归属 · ${esc(c.name)}</h3><p>${esc(m.reason)}</p><p class="sub">原分析对象：${esc(m.sourceProductType)}。目录仅保留一个主归属，不等于该技术仅适用一种产品，也不证明官网型号实施。</p></section>`:'';}
let portraitData={topics:[],mappings:[]},portraitById={},portraitMap={};
function initPortraits(data){
 if(!data?.topics?.length||!data?.mappings?.length)throw Error('功能画像归并数据缺失');
 portraitData=data;portraitById=Object.fromEntries(data.topics.map(t=>[t.id,t]));portraitMap=Object.fromEntries(data.mappings.map(m=>[m.analysisId,m]));
 if(currentAnalyses.some(a=>!portraitMap[a.id]||portraitMap[a.id].topicIds.some(id=>!portraitById[id])))throw Error('功能画像覆盖不完整');
 for(const d of currentDocs){const m=portraitMap[currentAnalysis(d)?.id];currentSearchIndex[d.id]+=' '+(m?.topicIds||[]).map(id=>portraitById[id].name+' '+portraitById[id].overview).join(' ').toLowerCase();}
}
function portraitAssignedGroups(a,id,form){const m=portraitMap[a.id],assignment=m?.assignments?.find(x=>x.topicId===id),indexes=assignment?.formGroupIndexes||a.formGroups.map((_,i)=>i);return indexes.map(i=>a.formGroups[i]).filter(g=>g&&(!form||g.form===form));}
function portraitTopics(items,form,onlyTopic=''){const map=new Map();for(const a of items){for(const id of portraitMap[a.id]?.topicIds||[]){if(onlyTopic&&id!==onlyTopic||!portraitAssignedGroups(a,id,form).length)continue;if(!map.has(id))map.set(id,[]);map.get(id).push(a);}}return [...map].sort((a,b)=>b[1].length-a[1].length||a[0].localeCompare(b[0]));}
function portraitReference(a,form,ds,topicId){const d=currentById[a.id],gg=portraitAssignedGroups(a,topicId,form),matching=ds.filter(x=>x.applicationNumber===a.applicationNumber),versions=currentDocs.filter(x=>x.applicationNumber===a.applicationNumber);return `<article class="portrait-reference"><a href="${docLink(a.id)}"><b>${esc(a.id)}</b> · ${esc(d.title)}</a><p><b>本件路径：</b>${esc(a.function)}</p>${gg.map(g=>`<p>${esc(g.summary)}</p><p class="sub"><b>${esc(g.label||'分析依据')}</b> · ${form==='design'?'摘要图资料解读':'权 '+(g.claimNumbers||g.evidenceClaimNumbers||[]).join('、')} · ${esc(g.limitations)}</p>`).join('')}<p class="sub">${esc(currentLabel(a))} · ${esc(a.textVersion||d.patentType)} · ${esc(a.productType)}</p><p class="sub">本申请 ${versions.length} 个文献版本${currentQuery?'，当前匹配 '+matching.length+' 个':''}：${versions.map(v=>`<a href="${docLink(v.id)}">${esc(v.id)}</a>`).join(' · ')}</p><a href="${docLink(a.id)}">查看独立组合、原文、附图与来源 →</a></article>`;}
function portraitCard(id,items,form,key,ds){const t=portraitById[id],all=currentAnalyses.filter(a=>(portraitMap[a.id]?.topicIds||[]).includes(id)&&portraitAssignedGroups(a,id,form).length),docCount=ds.filter(d=>items.some(a=>a.applicationNumber===d.applicationNumber)).length,paths=[...new Set(items.map(a=>form==='design'?(a.formGroups.find(g=>g.form==='design')?.summary||a.function).split('。')[0]:a.function))],openKey=key+'-'+form+'-'+id,limit=currentGroupPages[openKey]||5;return `<article class="portrait-card"><h4>${esc(t.name)}</h4><p>${esc(t.formOverviews?.[form]||t.overview)}</p><p class="portrait-paths"><b>${form==='design'?'可见造型例：':'当前路径：'}</b>${paths.slice(0,2).map(esc).join('；')}${paths.length>2?'等 '+paths.length+' 条分析路径':''}。</p>${disclosure(openKey,`<strong>${items.length} 个引用申请 · ${docCount} 条匹配文献</strong><span class="sub">展开路径差异与引用 ↓</span>`,`<p class="sub">同一申请可关联多个主题；每件保持完整独立权利组合，主题不拆分或拼接权利要求。本主题全库涉及 ${all.length} 个${form==='design'?'外观':'该客体'}申请。下列仅为当前产品／筛选结果。</p>${items.slice(0,limit).map(a=>portraitReference(a,form,ds,id)).join('')}${items.length>limit?`<button class="button" data-current-more="${esc(openKey)}">继续查看其余 ${items.length-limit} 个申请</button>`:''}`,'portrait-citations')}</article>`;}
function expandedProductGroups(ds,view){
 view='products';
 if(!portraitData.mappings.length)return legacyCurrentGroups(ds,view);
 const matching=new Set(ds.map(d=>d.applicationNumber)),items=currentAnalyses.filter(a=>matching.has(a.applicationNumber)),forms=Object.entries(claimFormLabels).filter(([f])=>!currentFilter.form||currentFilter.form===f);
 let entries;
 if(view==='functions')entries=portraitTopics(items).map(([id,aa])=>[id,portraitById[id].name,aa]);
 else {const map=new Map();for(const a of items){const name=currentFamily(a,'products');if(!map.has(name))map.set(name,[]);map.get(name).push(a);}entries=[...map].map(([name,aa])=>[name,name,aa]).sort((a,b)=>primaryData.categories.findIndex(c=>c.name===a[0])-primaryData.categories.findIndex(c=>c.name===b[0]));}
 const visible=entries.slice(0,currentPage*16);
 return `<p class="scope-count">匹配 ${ds.length} 条文献 / ${matching.size} 个申请 · ${entries.length} 个${view==='functions'?'功能／设计主题':'产品类型'}。每个申请仅归一个主产品；各主产品申请数可相加。产品内跨主题、跨客体数量不可相加。</p><p class="sub">按主要技术对象组织产品目录，分类边界不表示权利范围互斥。产品内继续按方法、结构、外观查看功能主题与独立引用。</p><div class="current-group-list">${visible.map(([id,name,aa])=>{const key='portrait-'+view+'-'+encodeURIComponent(id),topics=portraitTopics(aa),counts=forms.map(([f,l])=>l+' '+portraitTopics(aa,f,view==='functions'?id:'').length+' 个主题').join(' · '),chips=topics.slice(0,6).map(([tid,as])=>`<span>${esc(portraitById[tid].name)} <b>${as.length}</b></span>`).join('');return disclosure(key,`<strong>${esc(name)}</strong><span class="sub">${aa.length} 个申请 · ${counts}</span>${view==='products'?`<span class="portrait-map">${chips}${topics.length>6?`<span>另 ${topics.length-6} 个主题</span>`:''}</span>`:''}`,`${primaryBoundary(name)}<div class="current-family-forms">${forms.map(([f,label])=>{const tt=portraitTopics(aa,f,view==='functions'?id:'');return `<section class="current-family-form ${f}"><h3>${formIcon(f)} ${label}<span class="sub">${tt.length} 个主题 · ${new Set(tt.flatMap(([,as])=>as.map(a=>a.applicationNumber))).size} 个申请</span></h3>${tt.map(([tid,as])=>portraitCard(tid,as,f,key,ds)).join('')||'<p class="sub">当前筛选无该类资料。</p>'}</section>`;}).join('')}</div>`,'current-group');}).join('')||'<div class="empty">没有匹配结果，请清除筛选。</div>'}</div>${entries.length>visible.length?'<button class="button" id="current-more-groups">加载更多主题／产品</button>':''}`;
}
let routeData={paths:[],subpaths:[],assignments:[]},routeById={},routePathById={},productReferences=[];
function initRoutes(data,refs){if(!data)throw Error('Missing route tree');routeData=data;routeById=Object.fromEntries(data.subpaths.map(t=>[t.id,t]));routePathById=Object.fromEntries(data.paths.map(t=>[t.id,t]));productReferences=refs||[];}
function routeGroups(a,id,form){return [...new Set(routeData.assignments.filter(e=>e.analysisId===a.id&&e.subpathId===id&&e.form===form).map(e=>e.formGroupIndex))].map(i=>a.formGroups[i]);}
function routeTopics(items,form){const ids=new Set(items.map(a=>a.id)),buckets=new Map();for(const e of routeData.assignments){if(!ids.has(e.analysisId)||e.form!==form)continue;if(!buckets.has(e.subpathId))buckets.set(e.subpathId,new Set());buckets.get(e.subpathId).add(e.analysisId);}return routeData.subpaths.filter(t=>buckets.has(t.id)).map(t=>[t.id,items.filter(a=>buckets.get(t.id).has(a.id))]);}
function routeProductReference(t,items,product){const refs=productReferences.filter(r=>r.products.includes(product.id)&&r.paths.includes(t.pathId)&&!items.some(a=>(r.exclude||[]).includes(a.id)));return `<aside class="route-products"><b>华测导航（CHCNAV） · 产品参考</b>${refs.length?refs.map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.name)} ↗</a> · ${esc(r.use)}</p><small>官网核验 ${r.verified} · 官网产品参考，未核实采用所引专利</small>`).join(''):`<p>产品类型：${esc(product.name)}</p><small>依据现有分析的技术对象归类；该子路径尚无已核实的具体型号关联。</small>`}</aside>`;}
// Counts and ordering derive from the existing assignments; no analysis is synthesized.
const readerApplicationCount=items=>new Set(items.map(a=>a.applicationNumber)).size;
let reader={product:'',form:'method',topic:'',limit:4,refsOpen:false,mobileList:false,openPath:'',audience:'rd'};
function resetReader(product='',form='method'){const audience=reader.audience||'rd';reader={product,form,topic:'',limit:4,refsOpen:audience==='ip',mobileList:false,openPath:'',audience};}
function readerRankedPaths(topics){
 return routeData.paths.map(path=>{const children=topics.filter(([id])=>routeById[id].pathId===path.id).sort((a,b)=>readerApplicationCount(b[1])-readerApplicationCount(a[1])||a[0].localeCompare(b[0]));return {path,children,count:readerApplicationCount(children.flatMap(([,items])=>items))};}).filter(row=>row.children.length).sort((a,b)=>b.count-a.count||a.path.id.localeCompare(b.path.id));
}
function readerModel(ds){
 const matches=new Set(ds.map(d=>d.applicationNumber)),items=currentAnalyses.filter(a=>matches.has(a.applicationNumber));
 const products=primaryData.categories.filter(c=>items.some(a=>primaryFor(a)?.id===c.id)).sort((a,b)=>readerApplicationCount(items.filter(x=>primaryFor(x)?.id===b.id))-readerApplicationCount(items.filter(x=>primaryFor(x)?.id===a.id))||a.id.localeCompare(b.id));
 if(!products.length)return {products,items:[],topics:[],paths:[],product:null};
 const product=products.find(c=>c.id===(currentFilter.product||reader.product))||products[0];
 if(reader.product!==product.id)resetReader(product.id,currentFilter.form||'method');
 const aa=items.filter(a=>primaryFor(a)?.id===product.id),available=['method','structure','design'].filter(f=>routeTopics(aa,f).length);
 if(currentFilter.form)reader.form=currentFilter.form;
 if(!available.includes(reader.form))reader.form=available[0]||'method';
 const paths=readerRankedPaths(routeTopics(aa,reader.form)),topics=paths.flatMap(p=>p.children);
 if(!topics.some(([id])=>id===reader.topic)){reader.topic=topics[0]?.[0]||'';reader.limit=4;reader.refsOpen=reader.audience==='ip';reader.openPath=routeById[reader.topic]?.pathId||'';}
 return {products,product,items:aa,topics,paths,available};
}
function readerShort(t){const text=t.summary||routePathById[t.pathId]?.principle||t.name;return text.split(/[；。]/)[0]+'。';}
function readerProductHero(product,items){
 const refs=productReferences.filter(r=>r.products.includes(product.id)),imageModel=refs.map(r=>models.find(m=>m.model.toLowerCase()===r.name.toLowerCase())).find(m=>m?.localImage);
 return `<section class="reader-product-hero"><div class="reader-product-copy"><span class="eyebrow">竞争对手 · 华测导航（CHCNAV）</span><h2>${esc(product.name)}</h2><p class="reader-product-purpose">${esc(product.include)}</p><div class="reader-product-facts"><span><b>${readerApplicationCount(items)}</b> 个去重申请</span><span>每申请一个主产品归属</span></div><p class="reader-product-sources">官网产品辅助参考：${refs.length?refs.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.name)} ↗</a>`).join(' · '):'尚无已核实的具体型号对应；按专利技术对象归类。'}</p><small>${refs.length?`来源核对日期 ${esc([...new Set(refs.map(r=>r.verified))].join('、'))} · `:''}产品信息帮助理解用途，不认定具体型号实施所引专利。</small></div>${imageModel?`<figure class="reader-product-image"><img src="${esc(imageModel.localImage)}" alt="${esc(imageModel.model)} 官网产品参考图片，不表示专利实施关联" loading="lazy"><figcaption>${esc(imageModel.model)} · <a href="${esc(imageModel.detailUrl)}" target="_blank" rel="noopener">图片来源 ↗</a></figcaption></figure>`:''}</section>`;
}
function readerReferences(items,form,topic,ds){
 const sorted=[...items].sort((a,b)=>(currentById[b.id]?.pubDate||'').localeCompare(currentById[a.id]?.pubDate||'')||a.id.localeCompare(b.id));
 return sorted.slice(0,reader.limit).map(a=>{
  const d=currentById[a.id],gg=routeGroups(a,topic,form),numbers=[...new Set(gg.flatMap(g=>g.claimNumbers||g.evidenceClaimNumbers||[]))],versions=currentDocs.filter(v=>v.applicationNumber===a.applicationNumber);
  return `<article class="reader-reference"><div class="reader-reference-head"><a href="${docLink(a.id)}"><b>${esc(a.id)}</b> · ${esc(d.title)}</a><span class="badge unknown">${esc(d.patentType)}</span></div><p class="reader-reference-direction">${esc(a.function)}</p>${reader.audience==='ip'?`<p class="reader-reference-meta">${esc(a.textVersion||d.patentType)} · ${form==='design'?'外观图文资料':numbers.length?'权利要求 '+numbers.join('、'):'具体权项编号须核对原文'} · ${esc(d.pubDate)}</p><p class="current-status-note">${currentKnownStatus(a.id)}</p>`:''}<details class="reader-evidence"><summary>${form==='design'?'查看本件外观资料与限制':'查看本件技术特征组合与限制'}${form!=='design'&&numbers.length?' · 权 '+numbers.join('、'):''}</summary><p class="sub"><b>技术对象：</b>${esc(a.productType)} · <b>分析版本：</b>${esc(a.textVersion||d.patentType)} · <a href="${esc(a.sourceUrl||currentSource(d))}" target="_blank" rel="noopener">分析来源 ↗</a></p>${gg.map(g=>`<section class="reader-evidence-group"><h5>${esc(g.label||claimFormLabels[g.form])}${form!=='design'?' · 权 '+(g.claimNumbers||g.evidenceClaimNumbers||[]).map(esc).join('、'):''}</h5><p>${esc(g.summary||'此项未提供可核对的组合说明，请查看原文。')}</p>${g.limitations?`<p class="reader-evidence-limit"><b>关键限制：</b>${esc(currentStrings(g.limitations).join('；'))}</p>`:''}</section>`).join('')}<p class="sub">${esc(currentLabel(a))}${a.analysisCompleteness==='limited'?' · 原文存在局部缺口':''}。各件及各权项分别阅读，不将本页技术方向当作共同保护组合。</p><p class="sub">同申请文献：${versions.map(v=>`<a href="${docLink(v.id)}">${esc(v.id)}</a>`).join(' · ')}；其他版本范围须分别核对。</p></details><div class="reader-reference-actions">${pdfLinks(a.id,true)}<a class="sub" href="${docLink(a.id)}">完整分析、权利要求、状态与证据 →</a></div></article>`;
 }).join('')+(items.length>reader.limit?`<button class="button" id="reader-more">再显示 ${Math.min(4,items.length-reader.limit)} 个申请（余 ${items.length-reader.limit}）</button>`:'');
}
function currentGroups(ds,view){
 if(!primaryData.mappings.length)return expandedProductGroups(ds,'products');
 const m=readerModel(ds);if(!m.product)return '<div class="empty reader-empty">无匹配产品或专利。请清除筛选。</div>';
 const [topicId,items]=m.topics.find(([id])=>id===reader.topic)||['',[]],t=routeById[topicId],path=t&&routePathById[t.pathId],selectedPath=m.paths.find(p=>p.path.id===t?.pathId),docsInProduct=ds.filter(d=>m.items.some(a=>a.applicationNumber===d.applicationNumber)),formApps=readerApplicationCount(m.topics.flatMap(([,aa])=>aa)),topicDocs=ds.filter(d=>items.some(a=>a.applicationNumber===d.applicationNumber)).length,shortDirections=[...new Set(items.map(a=>a.function).filter(Boolean))];
 return `<section class="reader-workspace ${reader.mobileList?'show-directory':''}" data-reader-mode="${reader.audience}" aria-label="产品紧凑阅读工作区">${readerProductHero(m.product,m.items)}<div class="reader-heading"><p class="scope-count">当前匹配 ${docsInProduct.length} 条文献 · ${m.products.length} 类产品${!currentFilter.product?'，可在上方切换':''}</p><details class="reader-boundary"><summary>分类边界</summary>${primaryBoundary(m.product.name)}</details></div><div class="reader-tabs" role="tablist" aria-label="保护客体">${Object.entries(claimFormLabels).map(([f,label])=>{const topics=routeTopics(m.items,f),count=readerApplicationCount(topics.flatMap(([,aa])=>aa));return `<button type="button" role="tab" id="reader-tab-${f}" aria-selected="${reader.form===f}" aria-controls="reader-panel" tabindex="${reader.form===f?'0':'-1'}" data-reader-form="${f}" ${!topics.length?'disabled':''}>${formIcon(f)} ${label}<span>${count} 申请 · ${topics.length} 子路径</span></button>`;}).join('')}</div><div class="reader-toolbar"><p class="reader-caveat">${m.paths.length} 条${reader.form==='design'?'设计路径':'技术路径'} · ${m.topics.length} 个子路径 · ${formApps} 个去重申请</p><div class="reader-audience" role="group" aria-label="阅读侧重"><button type="button" data-reader-audience="rd" aria-pressed="${reader.audience==='rd'}">研发速览</button><button type="button" data-reader-audience="ip" aria-pressed="${reader.audience==='ip'}">知识产权核对</button></div></div><p class="reader-order-note">路径及子路径按当前匹配的去重申请数从多到少排列；相同数量按固定编号排序。该排序表示资料关联量，不代表重要性、有效性或侵权风险。</p><div class="reader-mobile-picker"><label for="reader-topic-select">技术路径 → 子路径</label><select id="reader-topic-select">${m.paths.map(row=>`<optgroup label="${esc(row.path.name)} · ${row.count} 申请">${row.children.map(([id,aa])=>`<option value="${id}" ${id===topicId?'selected':''}>${esc(routeById[id].name)} · ${readerApplicationCount(aa)} 申请</option>`).join('')}</optgroup>`).join('')}</select><button type="button" id="reader-directory-toggle" aria-expanded="${reader.mobileList}">${reader.mobileList?'返回选中子路径':'查看全部路径目录'}</button></div><div class="reader-layout" id="reader-panel" role="tabpanel" aria-labelledby="reader-tab-${reader.form}"><nav class="reader-directory" aria-label="当前产品的路径树">${m.paths.map((row,i)=>`<details class="route-branch" data-route="${row.path.id}" ${reader.openPath===row.path.id?'open':''}><summary><span class="reader-route-rank">${String(i+1).padStart(2,'0')}</span><span><b>${esc(row.path.name)}</b><small>${row.count} 申请 · ${row.children.length} 子路径</small><span class="reader-route-direction">${esc(row.path.principle)}</span></span></summary>${row.children.map(([id,aa])=>`<button type="button" data-reader-topic="${id}" aria-current="${id===topicId?'true':'false'}"><span><b>${esc(routeById[id].name)}</b><em>${readerApplicationCount(aa)}</em></span></button>`).join('')}</details>`).join('')}</nav><section class="reader-detail" aria-live="polite" aria-label="选中主题详情">${t?`<div class="reader-detail-title"><span class="eyebrow">${esc(m.product.name)} / ${esc(claimFormLabels[reader.form])}</span><h3>${esc(path.name)}</h3><p class="reader-route-purpose"><b>解决的问题／应用方向</b>${esc(path.principle)}</p><span class="reader-route-count">本路径 ${selectedPath.count} 个申请 · ${selectedPath.children.length} 个子路径</span></div><div class="reader-subpath-heading"><span>当前子路径</span><h4>${esc(t.name)}</h4><span class="badge">${readerApplicationCount(items)} 个引用申请 · ${topicDocs} 条匹配文献</span></div><div class="reader-technical-focus"><h5>${reader.form==='design'?'图文归纳方向':'技术方案要点'}</h5><p>${esc(t.summary||path.principle)}</p><small>依据现有分析归纳阅读方向；各专利必要组合与限制分别见引用，不将不同权利要求拼接。</small></div>${shortDirections.length?`<h4 class="reader-directions-title">${reader.form==='design'?'本子路径的设计资料方向':'本子路径涉及的方案方向'}</h4><ul class="reader-paths">${shortDirections.slice(0,3).map(direction=>`<li>${esc(direction)}</li>`).join('')}</ul>${shortDirections.length>3?`<p class="sub">另有 ${shortDirections.length-3} 个方案方向，随引用逐件查看。</p>`:''}`:''}<details class="reader-references" ${reader.refsOpen?'open':''}><summary>引用专利 <b>${readerApplicationCount(items)}</b><span>${reader.audience==='ip'?'逐件核对权项与版本':'按需展开独立方案'}</span></summary><p class="sub">${reader.form==='design'?'完整 PDF 视图入口与图文核对状态见各件详情；图像存在不等于保护范围已核验。':'必要技术特征、关系和限制按原文版本独立保留；法律状态未由本页确认。'}</p>${readerReferences(items,reader.form,topicId,ds)}</details>`:'<p>当前层面没有匹配主题。</p>'}</section></div></section>`;
}
function readerRefresh(focusSelector){currentRender();if(focusSelector)$(focusSelector)?.focus({preventScroll:true});}
function selectReaderTopic(id){if(!routeById[id])return;reader.topic=id;reader.openPath=routeById[id].pathId;reader.limit=4;reader.refsOpen=reader.audience==='ip';reader.mobileList=false;readerRefresh(`[data-reader-topic="${id}"]`);if(window.matchMedia('(max-width: 700px)').matches){$('#reader-topic-select')?.focus({preventScroll:true});$('.reader-workspace')?.scrollIntoView({block:'start'});}}
function bindReader(){
 document.querySelectorAll('[data-route]').forEach(el=>el.addEventListener('toggle',()=>{if(!el.isConnected)return;if(el.open){reader.openPath=el.dataset.route;document.querySelectorAll('[data-route]').forEach(other=>{if(other!==el)other.open=false;});}}));
 document.querySelectorAll('[data-reader-topic]').forEach(b=>b.onclick=()=>selectReaderTopic(b.dataset.readerTopic));
 $('#reader-topic-select')?.addEventListener('change',e=>selectReaderTopic(e.target.value));
 $('#reader-directory-toggle')?.addEventListener('click',()=>{reader.mobileList=!reader.mobileList;readerRefresh('#reader-directory-toggle');});
 document.querySelectorAll('[data-reader-audience]').forEach(b=>b.onclick=()=>{reader.audience=b.dataset.readerAudience;reader.refsOpen=reader.audience==='ip';readerRefresh(`[data-reader-audience="${reader.audience}"]`);});
 document.querySelectorAll('[data-reader-form]').forEach(b=>{b.onclick=()=>{const f=b.dataset.readerForm;reader.form=f;reader.topic='';reader.refsOpen=reader.audience==='ip';reader.limit=4;reader.mobileList=false;currentFilter.form='';readerRefresh('#reader-tab-'+f);};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-reader-form]:not(:disabled)')],i=tabs.indexOf(b),j=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[j].click();};});
 $('.reader-references')?.addEventListener('toggle',e=>{if(e.target.isConnected)reader.refsOpen=e.target.open;});
 $('#reader-more')?.addEventListener('click',()=>{reader.limit+=4;reader.refsOpen=true;readerRefresh('#reader-more');});
}

function currentLibrary(ds){return `<p class="scope-count">匹配 ${ds.length} 条文献 / ${new Set(ds.map(d=>d.applicationNumber)).size} 个申请。每申请的分析来源版本单列，不将 B 版结论直接当成 A 版范围。</p><div class="current-library">${ds.slice(0,currentPage*30).map(d=>{const a=currentAnalysis(d);return `<article class="scope-record"><a href="${docLink(d.id)}"><b>${esc(d.id)}</b> ${esc(d.title)}</a><p class="sub">${esc(d.patentType)} · ${esc(currentLabel(a))}${a&&a.id!==d.id?' · 本申请分析来源 '+esc(a.id):''}</p>${pdfLinks(d.id,true)}</article>`}).join('')||'<div class="empty">无匹配文献。</div>'}</div>${ds.length>currentPage*30?'<button class="button" id="current-more-groups">加载更多文献</button>':''}`;}
function currentDetail(id){const d=currentById[id];if(!d)return '<p>未找到文献。</p>';const a=currentAnalysis(d),text=currentTexts[id],same=currentDocs.filter(x=>x.applicationNumber===d.applicationNumber);return `<h1>${esc(d.title)}</h1><p><b>${esc(id)}</b> · ${esc(d.patentType)} · ${esc(d.applicationNumber)}</p><p>${currentKnownStatus(id)}</p>${pdfLinks(id)}${window.DesignViews?.render(id)||''}<p class="scope-warning">${/A$/.test(id)?'本件为公开申请方案，不等于已取得授权。':'文献类型不代表当前法律有效性。'}当前权属与法律状态未由本批资料确认。</p><p><a href="${esc(currentSource(d))}" target="_blank" rel="noopener">对应文献来源 ↗</a> · ${same.map(x=>`<a href="${docLink(x.id)}">${esc(x.id)}</a>`).join(' · ')}</p>${a?`<p class="sub">${esc(currentLabel(a))} · 分析来源 <a href="${docLink(a.id)}">${esc(a.id)}</a>${a.id!==id?'；以下分析不自动等同本版本范围。':''}</p>${currentDesign(a)?'<p class="scope-warning">既有分析依据简要说明／摘要图。新增 PDF 原页和视图供逐件核对，不自动将既有解读升级为完整外观保护范围结论。</p>':''}${(a.formGroups||[]).map(g=>currentForm(g,a,false)).join('')}${primaryDetail(a)}${currentDetailNotes(a)}${currentDesign(a)?disclosure('original-design-image-'+id,'原有摘要附图与来源（保留）',currentDesignImage(a,d)):currentDesignImage(a,d)}`:'<p>本条完整保留于文献库，未提供本批分析。不能由摘要补写权利范围。</p>'}${text?.claims?.length?disclosure('current-raw-'+id,`权利要求原文（${text.claims.length} 项）`,currentRawClaims(text,id)):''}${disclosure('current-abstract-'+id,d.patentType==='外观设计'?'上传简要说明与元信息':'原始摘要与元信息',`<p>${esc(d.abstract)}</p><p>申请人：${esc(d.applicants)}</p><p>申请日：${esc(displayDate(d.filingDate))} · 公告／公开日：${esc(displayDate(d.pubDate))}</p>`)}${byClaim[id]&&scopeBy[id]?.analysisStatus==='analyzed'?disclosure('current-legacy-'+id,'保留的逐件深度分析与来源（原版本）',patentDetails(id,new URLSearchParams())):''}`;}
function currentDetailNotes(a){return [['从属限定与引用关系',a.dependentHighlights],['摘要与权利要求的区别',a.abstractVsClaims],['分析依据',a.analysisBasis],['导出字段交叉核对',a.exportFieldNotes],['来源限制与未确认事项',a.sourceLimitations]].map(([title,value])=>currentStrings(value).length?`<section class="detail-panel"><h3>${title}</h3>${currentStrings(value).map(t=>`<p>${esc(t)}</p>`).join('')}</section>`:'').join('');}
function currentDesignImage(a,d){const image=a.image||a.imageUrl||a.localImage||d.abstractImage||d.image||d.imageUrl||d.localImage;if(!image)return '';const url=typeof image==='string'?image:image.localUrl||image.url;if(!url)return '';return `<figure class="current-design-image"><a href="${esc(url)}" target="_blank" rel="noopener"><img src="${esc(url)}" alt="${esc(d.id)} 上传资料中的摘要附图" loading="lazy"></a><figcaption>上传资料中的摘要附图，不代表全部专利附图或完整外观授权视图组。</figcaption></figure>`;}
function currentRawClaims(t,id){if(!t?.claims?.length)return '<p>本条没有可展示的技术权利要求全文；外观简要说明不能充作技术权利要求。</p>';return `${t.exportFieldComparison?`<p class="scope-warning">${esc(t.exportFieldComparison.observation)} ${esc(t.exportFieldComparison.recommendation)}</p><details><summary>同文件导出字段对照（不替换V原文）</summary><h4>Q 首项列</h4><p class="raw-claim">${esc(t.exportFieldComparison.Q)}</p><h4>T 独立项摘录</h4><p class="raw-claim">${esc(t.exportFieldComparison.TIndependentExcerpt)}</p><p class="sub">Q/T/V均来自上传文件，不是独立官方认证。</p></details>`:''}${t.plainTextComplete===false||t.formulaImagesMayBeOmitted?'<p class="scope-warning">文本提取存在公式或排版缺口，不能当作完整公式依据。</p>':''}${t.localPdf?`<a href="${esc(t.localPdf)}" target="_blank" rel="noopener">缓存 PDF ↗</a>`:''}${t.claims.map(c=>`<details><summary>权利要求 ${esc(c.number)}</summary><p class="raw-claim">${esc(c.text)}</p></details>`).join('')}`;}
function openCurrentPatent(id){if(!currentById[id])return;drawerOrigin=document.activeElement;let dialog=$('#patent-drawer');if(!dialog){dialog=document.createElement('dialog');dialog.id='patent-drawer';dialog.setAttribute('aria-label','专利详情');document.body.append(dialog);dialog.addEventListener('close',()=>drawerOrigin?.focus?.());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});}dialog.innerHTML=`<div class="drawer-top"><strong>专利详情 · ${esc(id)}</strong><button id="drawer-close" aria-label="关闭专利详情">关闭 ×</button></div><div class="drawer-content">${currentDetail(id)}</div>`;$('#drawer-close').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;$('#drawer-close').focus();bindReviews();window.DesignViews?.bind(dialog);}
function currentBind(){const input=$('#current-q');if(input){input.oninput=e=>{if(e.isComposing)return;currentQuery=e.target.value;currentPage=1;const start=e.target.selectionStart;currentRender();const next=$('#current-q');next?.focus();next?.setSelectionRange(start,start);};$('#current-clear').onclick=()=>{currentQuery='';currentFilter={status:'',form:'',product:''};resetReader();currentPage=1;currentRender();};}for(const key of ['status','form','product'])$('#current-'+key)?.addEventListener('change',e=>{saveView();currentFilter[key]=e.target.value;if(key==='product'){resetReader(e.target.value);if(document.body.classList.contains('compact-product-view'))currentFilter.form='';}if(key==='form'){reader.topic='';reader.refsOpen=false;}currentPage=1;currentRender();if(key==='product'&&window.matchMedia('(max-width:700px)').matches)$('.reader-workspace')?.scrollIntoView({block:'start'});});$('#current-more-groups')?.addEventListener('click',()=>{saveView();currentPage++;currentRender();});document.querySelectorAll('[data-current-more]').forEach(b=>b.onclick=()=>{saveView();currentGroupPages[b.dataset.currentMore]=(currentGroupPages[b.dataset.currentMore]||6)+6;currentRender();});document.querySelectorAll('[data-open-key]').forEach(el=>el.ontoggle=()=>el.open?openNodes.add(el.dataset.openKey):openNodes.delete(el.dataset.openKey));}
function currentRender(){if(!currentReady)return false;if(/^#functions(?:[/?]|$)/.test(location.hash)){history.replaceState(null,'','#products');}const raw=location.hash.slice(1)||'products',[view,id]=raw.split('?')[0].split('/');if(['models','product'].includes(view))return false;const changed=lastView!==raw;if(changed)currentPage=1;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+view));document.body.classList.toggle('compact-product-view',!['patent','patents','updates','monitor'].includes(view));const ds=currentFiltered();$('#app').innerHTML=view==='monitor'?(window.PatentMonitor?.render()||'<section class="detail-panel"><h1>专利监控</h1><p>监控模块未能载入，请刷新重试。现有专利画像仍可使用。</p></section>'):view==='patent'?currentDetail(decodeURIComponent(id||'')):view==='updates'?currentHeader('')+'<h2>本次资料与保留历史</h2><p>本次使用用户提供 Excel，原始 v13 数据未覆盖。分析完成度仅按实际加载的记录状态统计。</p>'+disclosure('current-history','查看原版本更新与来源',scopeUpdates()):currentHeader(view==='functions'?'functions':'products')+(view==='patents'?currentLibrary(ds):currentGroups(ds,view==='functions'?'functions':'products'));currentBind();bindReader();window.DesignViews?.bind(document);if(view==='monitor')window.PatentMonitor?.bind(document);lastView=raw;if(changed)window.scrollTo(0,0);return true;}
async function loadCurrentModel(){const names=['portfolio-current','full-analysis','claim-texts-current','baseline-current','function-taxonomy','function-portraits','product-portraits','route-tree','official-product-references'];const results=await Promise.all(names.map(async name=>{try{const r=await fetch('data/'+name+'.json');return r.ok?await r.json():null;}catch{return null;}}));if(!results[0]&&!results[1])return;if(!results[0]||!results[1]){currentLoadIssue='本次资料尚未完整载入，当前显示保留的原版本。';return;}try{currentInit(results[0],results[1],results[2],results[3],results[4]);initPortraits(results[5]);initPrimaryProducts(results[6]);initRoutes(results[7],results[8]);}catch(e){currentLoadIssue='新资料关联校验未通过，当前显示保留的原版本。';console.error(e);}}

(async()=>{try{const data=await Promise.all(['portfolio','products','claims','product-catalog','product-relations','claim-texts','baseline','updates','application-groups','document-index','function-index','scope-index'].map(n=>fetch('data/'+n+'.json').then(r=>{if(!r.ok)throw Error(n);return r.json()})));[docs,categories,analyses,models,relations,texts,baseline,changes,groups]=data;const idx=Object.fromEntries(data[9].map(x=>[x.id,x]));docs=docs.map(d=>({...d,modules:idx[d.id]?.modules||[]}));byDoc=Object.fromEntries(docs.map(d=>[d.id,d]));byClaim=Object.fromEntries(analyses.map(c=>[c.id,c]));byText=Object.fromEntries(texts.map(t=>[t.id,t]));byModel=Object.fromEntries(models.map(m=>[m.id,m]));fx=data[10];fnBy=Object.fromEntries(fx.functions.map(f=>[f.id,f]));docFns=Object.fromEntries(fx.documents.map(d=>[d.id,d.functions]));scopeData=data[11];scopeBy=Object.fromEntries(scopeData.records.map(r=>[r.id,r]));typeBy=Object.fromEntries(scopeData.types.map(t=>[t.id,t]));scopeFnBy=Object.fromEntries(scopeData.functions.map(f=>[f.id,f]));scopeSchemeBy=Object.fromEntries(scopeData.schemes.map(s=>[s.id,s]));for(const c of scopeData.extraAnalyses)byClaim[c.id]=c;for(const t of scopeData.extraTexts)byText[t.id]=t;try{const probeResponse=await fetch('data/evidence-probe.json');if(probeResponse.ok){const probe=await probeResponse.json();if(Array.isArray(probe.attempts))evidenceProbe=probe;}}catch{}await Promise.all([loadCurrentModel(),loadPdfIndex(),window.DesignViews?.load()]);if(window.PatentMonitor){try{await window.PatentMonitor.load(currentDocs);}catch(error){console.warn('Monitor module could not be initialized',error);}}dualReady=true;render();if(currentLoadIssue&&!currentReady)$('#app').insertAdjacentHTML('afterbegin','<p class="scope-warning">'+esc(currentLoadIssue)+'</p>')}catch(e){console.error(e);$('#app').innerHTML='<div class="empty">资料未能完整载入。请刷新重试；原始数据保持保留。</div>'}})();
